window.BIBLIO = {"built": "2026-11-04", "categories": [{"id": "pediatrie", "label": "Pédiatrie générale", "blurb": "Les grands essais qui changent la pratique pédiatrique quotidienne.", "color": "#c2410c"}, {"id": "vaccins", "label": "Vaccins & infections communautaires", "blurb": "VRS, coqueluche, streptocoque A : prévention et épidémiologie de ville.", "color": "#0f766e"}, {"id": "sepsis", "label": "Sepsis & réanimation", "blurb": "Choc septique de l'enfant, définitions, remplissage, sepsis néonatal.", "color": "#b91c1c"}, {"id": "immunodeprimes", "label": "Immunodéprimés & fongiques", "blurb": "Neutropénie fébrile, candidoses, aspergillose et mucormycose.", "color": "#6d28d9"}, {"id": "ioa", "label": "Infections ostéo-articulaires", "blurb": "Ostéomyélite, arthrite septique, Kingella, prothèses et pied diabétique.", "color": "#a16207"}, {"id": "orl_resp", "label": "Respiratoire, ORL, peau & méninges", "blurb": "Pneumonies, infections ORL, méningites, infections cutanées.", "color": "#1d4ed8"}, {"id": "antiinfectieux", "label": "Anti-infectieux & antibioprophylaxie", "blurb": "Durées courtes, relais oral, prophylaxies, bon usage.", "color": "#047857"}, {"id": "adulte", "label": "Infectiologie adulte", "blurb": "Les essais majeurs et recommandations de l'infectiologie adulte.", "color": "#334155"}], "if_edition": "Journal Impact Factor 2024 — Clarivate JCR, édition 2025", "articles": [{"id": "pmid-42492562", "pmid": "42492562", "pmcid": "", "doi": "10.1016/s0140-6736(26)00879-2", "title": "Oral step-down, optimal drug, and total duration of antibiotic treatment in African children hospitalised with severe community-acquired pneumonia (PediCAP): a factorial randomised controlled trial", "title_fr": "PediCAP : relais oral précoce et traitement de 4 à 5 jours dans la pneumonie sévère de l'enfant", "authors_list": ["Bielicki JA", "Clements M", "Musiime V", "Moore DP", "Sidat M", "Mulenga V", "Mutata C", "Nalwanga D", "Waggie Z", "Chilundo J", "Chabala C", "Bwakura-Dangarembizi M", "Archary M", "Kiggwe A", "Dangor Z", "Spittle B", "Kapasa M", "Tagoola A", "Jeki C", "Sacarlal J", "Buck WC", "Chanda S", "Mujuru HA", "Giaquinto C", "Madhi SA", "Walker AS", "Sharland M", "PediCAP trial team"], "authors_short": "Bielicki JA et al.", "journal": "The Lancet", "journal_short": "Lancet", "year": 2026, "month_num": 7, "pub_date": "2026-07-23", "pub_date_fr": "juillet 2026", "volume": "408", "issue": "10554", "pages": "545-557", "pub_types": ["Comparative Study", "Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "orl_resp", "category_label": "Respiratoire, ORL, peau & méninges", "category_color": "#1d4ed8", "audience": "Enfant", "study_fr": "Essai factoriel randomisé · 13 hôpitaux d'Afrique subsaharienne · 1 101 enfants", "design": "Essai randomisé", "impact_factor": 88.5, "summary_fr": "Chez des enfants de 2 mois à 6 ans hospitalisés pour une pneumonie communautaire sévère non compliquée, un relais oral vers l'amoxicilline dès l'amélioration clinique, pour une durée totale de 4 à 5 jours, est non inférieur aux 5 jours d'antibiothérapie IV recommandés par l'OMS sur la réhospitalisation ou le décès à J28.", "key_points_fr": ["Comparaison amoxicilline vs amoxicilline-acide clavulanique en relais oral.", "Cinq durées totales testées, de 4 à 8 jours (IV + oral).", "Critère principal : réadmission ou décès à J28 (marge de non-infériorité +10 %).", "L'amoxicilline orale seule est la stratégie de relais retenue par les auteurs."], "pratique_fr": "Même pour les pneumonies sévères, le relais oral précoce et les durées courtes sont sûrs ; un argument de plus pour ne pas prolonger l'IV.", "tags": ["Pneumonie communautaire", "Relais oral", "Amoxicilline", "Durée courte"], "abstract_en": "Background — WHO recommends 5 days of intravenous antibiotics for children hospitalised with severe community-acquired pneumonia (CAP). We aimed to investigate the safety of a step-down to different oral antibiotics and the shortest effective duration.\n\nMethods — PediCAP was an open-label, parallel group, 2 × 5 factorial randomised controlled trial of children aged 2 months to 6 years hospitalised with severe CAP without complicating factors in 13 hospitals across five sub-Saharan African countries. Children weighing 3-30 kg and with point-of-care C-reactive protein of more than 10 mg/L were randomly assigned (5:5:1) to either a step-down from intravenous antibiotics to oral amoxicillin (250 mg) or amoxicillin-clavulanate (co-amoxiclav; 200 mg amoxicillin to 28·5 mg clavulanate) via dispersible tablets twice daily (superiority comparison) for five total (intravenous plus oral) durations (4-8 days; non-inferiority comparison), or a 5-day, fixed-duration, intravenous-only treatment (non-inferiority comparison). Children were stepped down when clinically improved and able to take oral antibiotics. Clinicians could change antibiotics if clinically indicated. The primary outcome was the proportion of readmission or death at day 28 (non-inferiority margin vs intravenous only: +10%). The study was registered with the ISRCTN registry (ISRCTN63115131) and is complete.\n\nFindings — Between Dec 7, 2020, and Aug 14, 2023, 2248 children were screened for eligibility and 1101 were randomly allocated (480 [43·6%] girls and 621 [56·4%] boys). The primary outcome was available in 1055 (95·8%) children. For children in the step-down groups, the mean total antibiotic exposure was 6·0 days (SD 3·5) in the 4-day group, 6·8 days (4·2) in the 5-day group, 7·4 (3·6) in the 6-day group, 8·3 days (3·4) in the 7-day group, and 9·2 days (2·9) in the 8-day group (p<0·0001), with 140 (68·6%) of 204, 151 (76·3%) of 198, 167 (85·2%) of 196, 179 (89·5%) of 200, and 186 (91·6%) of 203, respectively, stepping down within their randomised duration (p<0·0001). Primary outcomes occurred in 33 (6·9%) of 475 in the co-amoxiclav group, 27 (5·6%) of 484 in the amoxicillin group, and six (6·3%) of 96 in the intravenous-only group, with both oral step-down strategies non-inferior to the intravenous-only strategy (upper 95% CIs of 6·0 for co-amoxiclav and 5·7 for amoxicillin) and no evidence of superiority for co-amoxiclav over amoxicillin (adjusted risk difference 1·3% [95% CI -1·8 to 4·4]; p=0·40). Primary outcomes occurred in eight (4·1%) of 194 in the 4-day group, ten (5·3%) of 190 in the 5-day group, 16 (8·5%) of 188 in the 6-day group, 16 (8·3%) of 193 in the 7-day group, and ten (5·2%) of 194 in the 8-day group; all durations were non-inferior to the 8-day group (all upper 95% CIs ≤6·0%). There was no evidence of consistent differences in adverse events for oral antibiotic or duration comparisons. For antibiotic-related or serious adverse events, there was one (1·0%) in the intravenous-only group and 12 (2·5%) in the amoxicillin group (adjusted risk difference -2·3% [95% CI -4·2 to -0·3]; p=0·025), and 16 (3·4%) in the co-amoxiclav group (+0·8% [-1·2 to 2·8]; p=0·42); rates increased with randomised duration (slope estimate +0·9% [0·1 to 1·7]; p=0·032).\n\nInterpretation — For sub-Saharan African children hospitalised with severe CAP without complicating factors, a strategy of stepping down upon clinical improvement to oral amoxicillin after initial intravenous antibiotics, with a total treatment duration of 4-5 days, is non-inferior to WHO-recommended 5-day intravenous treatment.\n\nFunding — The Second European and Developing Countries Clinical Trials Partnership (EDCTP2).", "reading_min": 2, "pdf_file": "pdfs/PMID_42492562.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42492562/", "doi_url": "https://doi.org/10.1016/s0140-6736(26)00879-2", "pmc_url": "", "article_url": "https://doi.org/10.1016/s0140-6736(26)00879-2"}, {"id": "pmid-42308484", "pmid": "42308484", "pmcid": "PMC7619232", "doi": "10.1056/nejmoa2506905", "title": "Cefazolin for Methicillin-Susceptible Staphylococcus aureus Bacteremia", "title_fr": "SNAP : la céfazoline non inférieure aux pénicillines M dans les bactériémies à SAMS", "authors_list": ["Staphylococcus aureus Network Adaptive Platform (SNAP) Trial Group", "Lee TC", "Barina LA", "Walls G", "Goodman AL", "Yahav D", "Cheng MP", "Bonten M", "Bowen AC", "Boyles T", "Daneman N", "Ekkelenkamp MB", "Ghanem-Zoubi N", "Hensgens MPM", "Jager NGL", "Kaasch AJ", "Kouijzer IJE", "Lewis RJ", "Lumley T", "Lye DC", "McDonald EG", "McKew G", "McLean ARD", "McMullan BJ", "McQuilten ZK", "Morpeth SC", "Paterson DL", "Roberts JA", "Robinson JO", "Saito H", "Scarborough M", "Ten Oever J", "Turner RM", "Tverring J", "van Hal SJ", "Webb SA", "Whiteway LM", "Arias CA", "Henderson A", "Heriot GS", "Snelling TL", "Afra K", "Ali SS", "Amit S", "Anagnostou NA", "Archuleta S", "Aston SJ", "Athan E", "Baharav N", "Bai AD", "Barber BE", "Baskaran A", "Berkeley MMA", "Best EJ", "Bhilave NR", "Bloomfield MG", "Bond KA", "Bostock J", "Botheras CL", "Boyd MA", "Bradshaw SME", "Briggs EJ", "Britton PN", "Campbell AJ", "Carr BZ", "Chancellor JA", "Chen K", "Cheong EY", "Chew KL", "Chia PY", "Chomba R", "Chong BSW", "Clews CJN", "Cohen JM", "Commons RJ", "Cutfield T", "Daley P", "Daniel DS", "Davies J", "De P", "Denholm JT", "Di Virgilio M", "Dishon-Benattar Y", "Dotel R", "Duan EH", "Easom N", "Eliakim-Raz N", "England MM", "Fahmy M", "Findlater AR", "Flanagan KL", "Foo EZJ", "Foo H", "Forster DP", "Fralick M", "Frazer JL", "Gador-Whyte AP", "Garnham K", "German GJ", "Ghosh N", "Gisolf EH", "Giulieri SG", "Goulding SR", "Grant JM", "Gregson D", "Grimwade KC", "Grupper M", "Guy SD", "Gwee A", "Hall VG", "Hardy EJ", "Harris DJ", "Hatcher J", "Hobbs MR", "Holmes NE", "Howden BP", "Huggan PJ", "Jennings ZA", "Johnstone J", "Juniper T", "Kalimuddin S", "Kamfose M", "Kandel C", "Kelly MJ", "Kozak RA", "Kümin M", "Lamontagne F", "Lau JSY", "Lee IR", "Lin RJ", "Lindsay D", "Llewelyn MJ", "Longtin Y", "Lother SA", "Luey CE", "MacFadden DR", "Mahony AA", "Malden C", "Malhamé I", "Manning LA", "Marks M", "Martin LJ", "Matthews GV", "McGann PH", "McMahon JH", "Melon A", "Menon V", "Mertz D", "Meyer MP", "Molton JS", "Mora JM", "Moran E", "Mortimer LM", "Motaganahalli S", "Muller MP", "Munro APS", "Murray FA", "Murthy S", "Nagendra V", "Nel H", "New DWJ", "Nguyen V", "Norton G", "Norton KM", "Nourse CB", "Nye CJS", "O'Callaghan K", "O'Sullivan MVN", "Ong SWX", "Otu AA", "Owen M", "Papenburg J", "Parkes LO", "Paul M", "Perez-Patrigeon S", "Petersiel N", "Petrella L", "Pett SL", "Pham D", "Piazzese CJ", "Poulin S", "Rehak R", "Rennert-May E", "Richards AJ", "Rogers BA", "Sahng E", "Salada B", "Scheuerman O", "Schneider K", "Schulz TR", "Schwartz KL", "Simos PA", "Singh H", "Sinkeler FS", "Smith S", "Smith BJ", "Smith SW", "Somayaji R", "Sommerville C", "Song RXJ", "Sowden DC", "Stark MJ", "Stone NRH", "Strunk T", "Sud A", "Swe KP", "Symons CR", "Tan YE", "Ten Doesschate T", "Thien SY", "Thomas A", "Trad MA", "Tramontana AR", "Tsang JLY", "Ulett K", "Underwood J", "van Welzen BJ", "Vazquez-Grande G", "Velasquez Reyes DC", "Verberk JDM", "Voss LM", "Ward D", "Webb RH", "Whitmore TJ", "Wieder-Finesod A", "Wilson HL", "Wilson EW", "Wong HM", "Wong She K", "Wuerz T", "Yamamura DL", "Yeoh A", "Yow BLH", "Dymock M", "Mahar RK", "McGlothlin A", "Marsh JA", "Davis JS", "Tong SYC"], "authors_short": "Staphylococcus aureus Network Adaptive Platform (SNAP) Trial Group et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2026, "month_num": 6, "pub_date": "2026-06-01", "pub_date_fr": "juin 2026", "volume": "394", "issue": "23", "pages": "2329-2339", "pub_types": ["Comparative Study", "Equivalence Trial", "research-article", "Multicenter Study", "Randomized Controlled Trial", "Journal Article", "Clinical Trial, Phase IV"], "category_id": "adulte", "category_label": "Infectiologie adulte", "category_color": "#334155", "audience": "Adulte", "study_fr": "Essai plateforme adaptatif bayésien international · 1 287 patients évalués", "design": "Essai randomisé", "impact_factor": 78.5, "summary_fr": "Dans la plateforme SNAP, la céfazoline a été comparée à la flucloxacilline ou à la cloxacilline chez des adultes avec une bactériémie à S. aureus sensible à la méticilline. La céfazoline est non inférieure sur la mortalité à 90 jours (15,0 % vs 17,0 %, probabilité de non-infériorité 99,2 %) et entraîne moins d'insuffisance rénale aiguë.", "key_points_fr": ["Mortalité à J90 : 15,0 % (céfazoline) vs 17,0 % (pénicilline M).", "Probabilité de supériorité de la céfazoline : 89,8 %.", "Insuffisance rénale aiguë : 13,9 % vs 19,6 %.", "Concerne les SAMS résistants à la pénicilline."], "pratique_fr": "Avec CloCeBa, cet essai installe la céfazoline comme traitement de première ligne des bactériémies à SAMS, avec une meilleure tolérance rénale.", "tags": ["Staphylococcus aureus", "Bactériémie", "Céfazoline", "Cloxacilline", "SNAP"], "abstract_en": "Background — Staphylococcus aureus bacteremia is associated with high mortality. Whether cefazolin or an antistaphylococcal penicillin should be preferred for the treatment of methicillin-susceptible S. aureus bacteremia is unclear.\n\nMethods — In an ongoing international Bayesian adaptive platform trial, we conducted an open-label, randomized comparison of cefazolin with an antistaphylococcal penicillin (flucloxacillin or cloxacillin) in adult patients with penicillin-resistant, methicillin-susceptible S. aureus bacteremia. The primary outcome, which was evaluated with a hierarchical Bayesian logistic-regression model, was death from any cause within 90 days after enrollment in the platform. We assessed the posterior probability of the noninferiority of cefazolin to flucloxacillin or cloxacillin (with the criterion for noninferiority prespecified as an adjusted odds ratio of <1.2, which approximates an absolute difference in mortality of <2.5 percentage points if mortality in the antistaphylococcal-penicillin group is 15%), as well as the posterior probability of superiority (with the criterion of an adjusted odds ratio of <1.0). Secondary safety outcomes included the development of acute kidney injury within 14 days.\n\nResults — This domain of the ongoing trial was conducted between February 17, 2022, and August 7, 2024, by which time the criterion for noninferiority had been met. Mortality at 90 days among adults who could be evaluated was 15.0% (97 deaths among 645 patients) in the cefazolin group and 17.0% (109 deaths among 642 patients) in the antistaphylococcal-penicillin group (adjusted odds ratio, 0.81; 95% credible interval, 0.59 to 1.12; probability of noninferiority, 99.2%; probability of superiority, 89.8%). Acute kidney injury occurred in 92 of 660 patients (13.9%) in the cefazolin group, as compared with 127 of 648 (19.6%) in the antistaphylococcal-penicillin group (adjusted odds ratio, 0.67; 95% credible interval, 0.50 to 0.89; probability of superiority, 99.7%).\n\nConclusions — In patients with methicillin-susceptible S. aureus bacteremia, cefazolin was noninferior to flucloxacillin or cloxacillin with respect to 90-day mortality and was associated with a lower incidence of acute kidney injury. (Funded by the National Health and Medical Research Council and others; SNAP ClinicalTrials.gov number, NCT05137119.).", "reading_min": 2, "pdf_file": "pdfs/PMID_42308484.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42308484/", "doi_url": "https://doi.org/10.1056/nejmoa2506905", "pmc_url": "https://europepmc.org/article/PMC/PMC7619232", "article_url": "https://doi.org/10.1056/nejmoa2506905"}, {"id": "pmid-41276461", "pmid": "41276461", "pmcid": "", "doi": "10.1093/cid/ciaf627", "title": "Evaluating Personal and Environmental Decolonization Strategies for Children With Skin and Soft Tissue Infection and Their Households - A Randomized Clinical Trial", "title_fr": "Infections cutanées récidivantes à S. aureus : décoloniser l'enfant, la famille et la maison ?", "authors_list": ["Robinson AL", "Boyle MG", "Hogan PG", "Malone SM", "Krauss MJ", "Richardson LM", "Sullivan ML", "Walsh T", "Tal R", "Walsh L", "Thompson RM", "Parrish KL", "Muenks CE", "Burnham CD", "Fritz SA"], "authors_short": "Robinson AL et al.", "journal": "Clinical Infectious Diseases", "journal_short": "Clin Infect Dis", "year": 2026, "month_num": 5, "pub_date": "2026-05-01", "pub_date_fr": "mai 2026", "volume": "82", "issue": "5", "pages": "868-877", "pub_types": ["Research Support, Non-U.S. Gov't", "Randomized Controlled Trial", "Journal Article", "Research Support, N.I.H., Extramural"], "category_id": "orl_resp", "category_label": "Respiratoire, ORL, peau & méninges", "category_color": "#1d4ed8", "audience": "Enfant", "study_fr": "Essai randomisé ouvert · 196 enfants et 623 contacts familiaux", "design": "Essai randomisé", "impact_factor": 7.3, "summary_fr": "Après une infection cutanée à S. aureus chez un enfant, trois stratégies de décolonisation de 3 mois ont été comparées : personnelle (chlorhexidine, mupirocine), environnementale (désinfection des surfaces, linge) ou combinée. Aucune n'a réduit les infections à 3 mois. La stratégie combinée a réduit les récidives à 6 et 9 mois chez ceux qui avaient déjà eu une infection l'année précédente.", "key_points_fr": ["Pas de différence d'incidence pendant la période d'intervention de 3 mois.", "Bénéfice de l'approche combinée chez les patients avec antécédent d'infection cutanée dans l'année.", "Un antécédent d'infection est le principal facteur prédictif de récidive.", "Toutes les stratégies réduisent le portage de SARM, mais pas celui de SAMS."], "pratique_fr": "En cas de furonculose récidivante familiale, une décolonisation combinée personnelle et domestique peut se discuter, mais son effet reste modeste.", "tags": ["Staphylococcus aureus", "Infection cutanée", "Décolonisation", "Furonculose", "SARM"], "abstract_en": "Background — Staphylococcus aureus colonization predisposes to skin and soft tissue infection (SSTI). Given the waning effectiveness of decolonization, we evaluated periodic-personal decolonization and household environmental decontamination to reduce SSTIs among households affected by S. aureus.\n\nMethods — Households of children with community-associated S. aureus SSTI participated in an open-label randomized trial. After baseline decolonization, households were randomized 1:1:1 to a 3-month decolonization intervention: (1) periodic-personal (twice weekly chlorhexidine bathing and monthly intranasal mupirocin application); (2) environmental-hygiene (weekly household surface disinfection and enhanced laundry measures); or (3) integrated-approach of both periodic-personal and environmental-hygiene. Over 9 months, participants and household surfaces were sampled at 5 study visits to detect S. aureus; SSTI incidence was recorded. The primary outcome was household-level cumulative SSTI at 3 months, comparing the integrated-approach to the combined personal-periodic and environmental-hygiene groups.\n\nResults — Between 2015 and 2021, 196 index patients and their household contacts (n = 623) were enrolled. Cumulative SSTI incidence did not differ between groups during the 3-month intervention. In index patients and household contacts with SSTI in the year prior to enrollment, SSTI incidence was lower among the integrated-approach at 6- and 9-months compared to the combined periodic-personal and environmental-hygiene groups. In multivariable analyses, prior year SSTI was associated with subsequent SSTI; intervention group was not significant. All interventions reduced methicillin-resistant S. aureus, but not methicillin-susceptible S. aureus, personal colonization over 9 months.\n\nConclusions — While an integrated-approach of prolonged personal and environmental decolonization reduced SSTIs among participants with prior year SSTI, prior SSTI strongly predicted SSTI incidence longitudinally. Novel prevention strategies are needed.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41276461/", "doi_url": "https://doi.org/10.1093/cid/ciaf627", "pmc_url": "", "article_url": "https://doi.org/10.1093/cid/ciaf627"}, {"id": "pmid-42028918", "pmid": "42028918", "pmcid": "PMC13134814", "doi": "10.1056/nejmoa2601969", "title": "Balanced Fluid or 0.9% Saline in Children Treated for Septic Shock", "title_fr": "PRoMPT BOLUS : soluté balancé ou sérum salé à 0,9 % dans le choc septique de l'enfant", "authors_list": ["Balamuth F", "Weiss SL", "Long E", "Thompson GC", "Artis AS", "Campos AB", "Borland ML", "Dalziel SR", "Yock-Corrales A", "Singh R", "Williams A", "Mickiewicz B", "Hickey CP", "Fitzgerald JC", "Laskin BL", "Hickey RW", "Eckerle M", "Alqurashi W", "Alpern E", "Ambroggio L", "Badawy M", "Baumer-Mouradian S", "Berthelot S", "Clukies LD", "Craig S", "Curtis SJ", "Davis AL", "Duffy S", "Eisenberg MA", "Emsley JG", "Festekjian A", "George S", "Green R", "Gripp KE", "Jain PG", "Jani S", "Joubert GI", "Judge P", "Kam A", "Kochar A", "Koutroulis I", "Kwok MY", "Lane RD", "Lithgow A", "Lloyd J", "Mansour K", "McManemy JK", "Morris C", "Phillips N", "Rao A", "Rogers A", "Sehgal A", "Shayan Y", "Silverman J", "Tan E", "Uspal NG", "Vance C", "Whyte E", "Huang J", "Freedman SB", "Babl FE", "Kuppermann N", "PRoMPT BOLUS Investigators of the PECARN, PERC, and PREDICT Networks"], "authors_short": "Balamuth F et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2026, "month_num": 4, "pub_date": "2026-04-24", "pub_date_fr": "avril 2026", "volume": "395", "issue": "9", "pages": "870-881", "pub_types": ["Comparative Study", "research-article", "Multicenter Study", "Randomized Controlled Trial", "Pragmatic Clinical Trial", "Journal Article"], "category_id": "sepsis", "category_label": "Sepsis & réanimation", "category_color": "#b91c1c", "audience": "Enfant", "study_fr": "Essai randomisé pragmatique · 47 services d'urgences · 5 pays · plus de 9 000 enfants", "design": "Essai randomisé", "impact_factor": 78.5, "summary_fr": "Chez l'enfant traité pour un choc septique, le remplissage par un cristalloïde balancé n'a pas fait mieux que le sérum salé isotonique sur le critère composite décès, nouvelle épuration extrarénale ou dysfonction rénale persistante (3,4 % vs 3,0 %). Le soluté balancé entraîne moins d'hyperchlorémie et d'hypernatrémie, mais un peu plus d'hyperlactatémie.", "key_points_fr": ["8 482 enfants analysés, de 2 mois à l'adolescence.", "Critère principal : 3,4 % (balancé) vs 3,0 % (NaCl 0,9 %), RR 1,10, non significatif.", "Médiane de 23 jours vivants hors hôpital à J28 dans les deux groupes.", "Hyperchlorémie 31 % vs 49 % ; hyperlactatémie 20 % vs 17 %."], "pratique_fr": "Le choix du soluté de remplissage importe peu sur les événements graves : la rapidité et le volume du remplissage restent l'essentiel.", "tags": ["Choc septique", "Remplissage vasculaire", "Soluté balancé", "Urgences pédiatriques"], "abstract_en": "Background — Whether treatment with balanced crystalloid fluid leads to better outcomes than 0.9% saline in children treated for septic shock is debated.\n\nMethods — In this pragmatic clinical trial conducted at 47 emergency departments in five countries, patients (2 months to <18 years of age) with suspected septic shock and abnormal perfusion were randomly assigned to receive fluid resuscitation with either balanced fluid or 0.9% saline for up to 48 hours. The primary outcome was a major adverse kidney event (a composite of death, new renal-replacement therapy, or persistent kidney dysfunction) at 30 days after enrollment or hospital discharge, whichever occurred first.\n\nResults — Of 9041 enrolled patients, 277 (6.1%) in the balanced-fluid group and 282 (6.2%) in the 0.9%-saline group withdrew from the trial, leaving 4235 and 4247 patients, respectively, for analysis. A primary-outcome event occurred in 137 patients (3.4%) in the balanced-fluid group and in 124 (3.0%) in the 0.9%-saline group (difference, 0.4 percentage points; 95% confidence interval [CI], -0.5 to 1.3; risk ratio, 1.10; 95% CI, 0.88 to 1.40; P = 0.85). The median number of hospital-free days during 28 days after enrollment was 23 (interquartile range, 19 to 25) in both groups. Hyperchloremia occurred in 868 patients (31.4%) in the balanced-fluid group and in 1383 (49.0%) in the 0.9%-saline group; hypernatremia in 52 (1.8%) and 89 (3.1%), respectively; and hyperlactatemia in 260 (19.8%) and 228 (16.7%). No differences in other safety outcomes or adverse events were seen.\n\nConclusions — Among children treated for septic shock, no significant difference was seen in the incidence of death, new renal-replacement therapy, or persistent kidney dysfunction when fluid resuscitation was administered with balanced fluid as compared with 0.9% saline. (Funded by Eunice Kennedy Shriver National Institute of Child Health and Human Development and others; PRoMPT BOLUS ClinicalTrials.gov number, NCT04102371.).", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/42028918/", "doi_url": "https://doi.org/10.1056/nejmoa2601969", "pmc_url": "https://europepmc.org/article/PMC/PMC13134814", "article_url": "https://doi.org/10.1056/nejmoa2601969"}, {"id": "pmid-41428474", "pmid": "41428474", "pmcid": "PMC12723599", "doi": "10.1001/jama.2025.24082", "title": "Nirsevimab vs RSVpreF Vaccine for Respiratory Syncytial Virus-Related Hospitalization in Newborns", "title_fr": "Nirsévimab ou vaccination maternelle contre le VRS : la comparaison française à l'échelle nationale", "authors_list": ["Jabagi MJ", "Bertrand M", "Gabet A", "Kolla E", "Olié V", "Zureik M"], "authors_short": "Jabagi MJ et al.", "journal": "JAMA", "journal_short": "JAMA", "year": 2026, "month_num": 3, "pub_date": "2026-03-01", "pub_date_fr": "mars 2026", "volume": "335", "issue": "9", "pages": "787-798", "pub_types": ["Comparative Study", "research-article", "Journal Article"], "category_id": "vaccins", "category_label": "Vaccins & infections communautaires", "category_color": "#0f766e", "audience": "Enfant", "study_fr": "Cohorte nationale SNDS · saison 2024-2025 · 42 560 nouveau-nés appariés", "design": "Cohorte nationale", "impact_factor": 55.0, "summary_fr": "À partir du Système national des données de santé, les nouveau-nés protégés par la vaccination maternelle RSVpreF (32–36 SA) ont été comparés à ceux ayant reçu le nirsévimab avant la sortie de maternité. Le nirsévimab est associé à un risque d'hospitalisation pour infection respiratoire basse à VRS plus faible de 26 %, et à environ 40 % de formes graves en moins (réanimation, ventilation, oxygène).", "key_points_fr": ["481 hospitalisations : 212 dans le groupe nirsévimab vs 269 dans le groupe vaccin maternel.", "HR ajusté 0,74 pour l'hospitalisation, 0,58 pour l'admission en réanimation.", "HR 0,57 pour l'assistance ventilatoire et 0,56 pour l'oxygénothérapie.", "Résultats cohérents dans tous les sous-groupes ; première saison d'utilisation conjointe des deux stratégies."], "pratique_fr": "Les deux stratégies protègent, mais en France le nirsévimab semble offrir une meilleure protection du nouveau-né ; utile pour conseiller les familles en anténatal.", "tags": ["VRS", "Nirsévimab", "Abrysvo", "Vaccination maternelle", "SNDS"], "abstract_en": "Importance — Respiratory syncytial virus (RSV) is a leading cause of hospitalization in infants. The comparative effectiveness of 2 recently introduced preventive strategies (infant immunization through placental antibody transfer after maternal vaccination with the RSV prefusion F protein [RSVpreF] vaccine and passive infant immunization with nirsevimab) remains unknown.\n\nObjective — To compare the associations of maternal vaccination with the RSVpreF vaccine vs passive infant immunization with nirsevimab for the prevention of RSV-related hospitalization.\n\nDesign, setting, and participants — This population-based cohort study used data from the French National Health Data System. Maternal vaccination with the RSVpreF vaccine occurred during 32 to 36 weeks' gestation among infants born in mainland France between September 1 and December 31, 2024. Passive infant immunization with nirsevimab occurred prior to hospital discharge. Infants were matched 1:1 by maternity ward discharge date, sex, gestational age, and region. Follow-up ended at the time of RSV hospitalization or death or on February 28, 2025.\n\nExposures — Maternal immunization with the RSVpreF vaccine and passive infant immunization with nirsevimab.\n\nMain outcomes and measures — The primary outcome was hospitalization for RSV-associated lower respiratory tract infection. The secondary outcomes included admission to the pediatric intensive care unit (PICU), admission to high-dependency unit, ventilator support, and oxygen therapy. The hazard ratios (HRs) were estimated using conditional Cox proportional hazards models with inverse probability of treatment weighting.\n\nResults — A total of 42 560 infants (mean age, 3.7 [SD, 1.4] days; 51.7% male) were included in the study (21 280 per group) with a median follow-up of 84 days (IQR, 70-99 days). Of the 481 hospitalizations for RSV-associated lower respiratory tract infection, 212 (44.1%) occurred in the nirsevimab group vs 269 (55.9%) in the RSVpreF vaccine group (between-group difference, -11.8% [95% CI, -18.1% to -5.5%]). Compared with the RSVpreF vaccine, passive infant immunization with nirsevimab was associated with a lower risk of hospitalization for RSV-associated lower respiratory tract infection (adjusted HR, 0.74 [95% CI, 0.61 to 0.88]). Compared with the RSVpreF vaccine, passive infant immunization with nirsevimab was associated with a lower risk of severe outcomes, including PICU admission (adjusted HR, 0.58 [95% CI, 0.42 to 0.80]), requiring ventilator support (adjusted HR, 0.57 [95% CI, 0.40 to 0.81]), or requiring oxygen therapy (adjusted HR, 0.56 [95% CI, 0.38 to 0.81]). The results were consistent across subgroups and in the sensitivity analyses.\n\nConclusions and relevance — Compared with maternal vaccination with the RSVpreF vaccine, passive infant immunization with nirsevimab was associated with lower risks of RSV-related hospitalization and severe outcomes. These findings reflect the first RSV season with use of these immunization strategies in mainland France; their use should be reevaluated in future studies.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41428474/", "doi_url": "https://doi.org/10.1001/jama.2025.24082", "pmc_url": "https://europepmc.org/article/PMC/PMC12723599", "article_url": "https://doi.org/10.1001/jama.2025.24082"}, {"id": "pmid-41359996", "pmid": "41359996", "pmcid": "PMC12687202", "doi": "10.1001/jama.2025.24175", "title": "Precision Immunotherapy to Improve Sepsis Outcomes: The ImmunoSep Randomized Clinical Trial", "title_fr": "ImmunoSep : une immunothérapie de précision pour le sepsis", "authors_list": ["Giamarellos-Bourboulis EJ", "Kotsaki A", "Kotsamidi I", "Efthymiou A", "Koutsoukou V", "Ehler J", "Paridou A", "Frantzeskaki F", "Müller MCA", "Pickkers P", "Meylan S", "Nikolopoulos I", "Lupse M", "Gavala A", "Vlachogianni G", "Solomonidi N", "Alevizou A", "Kondili E", "Antoniadou E", "Nakou M", "Markou N", "Hatziagelaki E", "Prekates A", "Komnos A", "Bakkerus L", "Slim MA", "Dalekos GN", "Karapanagiotou A", "Ktena S", "De Pascale G", "Koulouras V", "Psarrakis C", "Massa E", "Dakou K", "Pazvanti C", "Ioakeimidou A", "Tsangaris I", "Antonakos N", "Vlaar APJ", "Anisoglou S", "Calandra T", "Papaioannou V", "Myrianthefs P", "Patrani M", "Alamanos I", "Antonelli M", "van der Meer JWM", "van der Poll T", "Wiersinga WJ", "Ntaganou M", "Gkeka E", "Bauer M", "Mouloudi E", "Netea MG", "ImmunoSep Study Group"], "authors_short": "Giamarellos-Bourboulis EJ et al.", "journal": "JAMA", "journal_short": "JAMA", "year": 2026, "month_num": 3, "pub_date": "2026-03-01", "pub_date_fr": "mars 2026", "volume": "335", "issue": "9", "pages": "775-786", "pub_types": ["Clinical Trial, Phase II", "research-article", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "adulte", "category_label": "Infectiologie adulte", "category_color": "#334155", "audience": "Adulte", "study_fr": "Essai de phase 2 randomisé en double aveugle · 6 pays · 276 patients", "design": "Essai randomisé (phase 2)", "impact_factor": 55.0, "summary_fr": "Les patients septiques ont été classés selon leur profil immunitaire : syndrome d'activation macrophagique (ferritine > 4 420 ng/mL), traité par anakinra, ou immunoparalysie, traitée par interféron gamma. Cette stratégie de précision a doublé la proportion de patients dont le score SOFA s'améliore nettement à J9 (35 % vs 18 %), sans différence significative de mortalité à J28.", "key_points_fr": ["Diminution du SOFA ≥ 1,4 point à J9 : 35,1 % vs 17,9 % sous placebo (p = 0,002).", "Anakinra si activation macrophagique ; interféron gamma si immunoparalysie.", "Pas de différence significative de mortalité à J28.", "Plus d'anémie sous anakinra et d'hémorragies sous interféron gamma."], "pratique_fr": "Une preuve de concept forte pour personnaliser le traitement immunologique du sepsis ; à confirmer en phase 3 avant toute utilisation en routine.", "tags": ["Sepsis", "Immunothérapie", "Anakinra", "Interféron gamma", "Médecine de précision"], "abstract_en": "Importance — Sepsis is heterogeneous, and the optimal strategy for tailoring immunotherapy is uncertain.\n\nObjective — To investigate whether precision immunotherapy guided by the presence of macrophage activation-like syndrome or sepsis-induced immunoparalysis improves organ dysfunction by day 9.\n\nDesign, setting, and participants — A randomized, double-blind, double-dummy, placebo-controlled clinical trial conducted in 6 countries. Patients with sepsis, defined by Sepsis-3, were included if they had community-acquired or hospital-acquired pneumonia or ventilator-associated pneumonia or bacteremia and sepsis and had displayed either macrophage activation-like syndrome (blood ferritin >4420 ng/mL) or sepsis-induced immunoparalysis (blood ferritin ≤4420 ng/mL and <5000 human leukocyte antigen DR receptors on CD45/CD14 monocytes). The first patient was enrolled August 5, 2021, and the last follow-up, April 29, 2024.\n\nInterventions — Eligible patients were randomized to receive standard care and precision immunotherapy or standard care and placebo. Those in the precision immunotherapy group with macrophage activation-like syndrome received anakinra intravenously (IV) and placebo subcutaneously, and those with sepsis-induced immunoparalysis received subcutaneous recombinant human interferon gamma and IV placebo. Those in the placebo group received both IV and subcutaneous placebo. Treatment was administered for up to 15 days.\n\nMain outcomes and measures — The primary end point was a decrease of at least 1.4 points in the mean Sequential Organ Failure Assessment (SOFA) score from baseline by day 9. The SOFA score evaluates 6 organ systems, ranging from 0, no dysfunction, to 4, failure, and the total score ranges from 0, normal, to 24, most severe form of multiorgan failure. Key secondary outcomes included 28-day mortality.\n\nResults — Of 672 patients assessed for eligibility, 281 were randomized and 276 were included in the primary analysis population (mean [SD] age, 70 [13] years; 93 females [33.7%]; median baseline SOFA score, 9 [IQR, 7-11]). The SOFA decrease end point was attained by 46 of 131 patients (35.1%) in the precision immunotherapy group and by 26 of 145 patients (17.9%) in the placebo group (difference, 17.2% [95% CI, 6.8% to 27.2%]; P = .002). Mortality at 28 days was not statistically significantly different between groups. A total of 1069 serious treatment-emergent adverse events (88.8%) were reported; increased incidence of anemia was noted in the anakinra group; and hemorrhage in the recombinant human interferon gamma group.\n\nConclusions and relevance — Among patients with sepsis, precision immunotherapy targeting macrophage activation-like syndrome and sepsis-induced immunoparalysis improved organ dysfunction by day 9 compared with placebo.\n\nTrial registration — ClinicalTrials.gov Identifier: NCT04990232.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41359996/", "doi_url": "https://doi.org/10.1001/jama.2025.24175", "pmc_url": "https://europepmc.org/article/PMC/PMC12687202", "article_url": "https://doi.org/10.1001/jama.2025.24175"}, {"id": "pmid-41359314", "pmid": "41359314", "pmcid": "PMC12687207", "doi": "10.1001/jama.2025.21454", "title": "Prediction of Bacteremia and Bacterial Meningitis Among Febrile Infants Aged 28 Days or Younger", "title_fr": "Nourrisson fébrile de 28 jours ou moins : la règle PECARN pour cibler la ponction lombaire", "authors_list": ["Burstein B", "Waterfield T", "Umana E", "Xie J", "Kuppermann N"], "authors_short": "Burstein B et al.", "journal": "JAMA", "journal_short": "JAMA", "year": 2026, "month_num": 2, "pub_date": "2026-02-01", "pub_date_fr": "février 2026", "volume": "335", "issue": "5", "pages": "425-433", "pub_types": ["Meta-Analysis", "research-article", "Multicenter Study", "Evaluation Study", "Journal Article"], "category_id": "pediatrie", "category_label": "Pédiatrie générale", "category_color": "#c2410c", "audience": "Enfant", "study_fr": "Analyse poolée de 4 cohortes prospectives · 6 pays · 1 537 nourrissons", "design": "Méta-analyse", "impact_factor": 55.0, "summary_fr": "La règle PECARN actualisée (bandelette urinaire négative, procalcitonine ≤ 0,5 ng/mL, polynucléaires neutrophiles ≤ 4 000/mm³) a été testée chez des nouveau-nés fébriles à terme, sans aspect toxique. Elle identifie 41 % de nourrissons à bas risque avec une sensibilité de 94 % et une valeur prédictive négative de 99,4 % pour les bactériémies et méningites bactériennes. Aucune méningite bactérienne n'a été classée à tort comme bas risque.", "key_points_fr": ["4,5 % d'infections bactériennes invasives, dont 0,7 % de méningites bactériennes.", "Sensibilité 94,2 %, spécificité 41,6 %, VPN 99,4 % pour l'infection bactérienne invasive.", "Aucune méningite manquée, dans l'analyse principale comme dans l'analyse secondaire (2 531 nourrissons).", "Concerne uniquement les nourrissons à terme, sans antécédent, sans aspect toxique."], "pratique_fr": "Chez le nouveau-né fébrile classé à bas risque PECARN, la ponction lombaire systématique peut faire l'objet d'une décision partagée avec les parents plutôt que d'être automatique.", "tags": ["Fièvre du nourrisson", "Méningite", "Procalcitonine", "Règle de décision", "Urgences pédiatriques"], "abstract_en": "Importance — Fever in the first month of life is often the only sign of life-threatening invasive bacterial infection, specifically bacteremia or bacterial meningitis. Most international guidelines recommend routine lumbar punctures for all febrile infants 28 days or younger to rule out bacterial meningitis. Clinical prediction rules may allow for select testing, but limited information exists on their performance to identify infants at low risk for invasive bacterial infections.\n\nObjective — To evaluate the diagnostic accuracy of the updated Pediatric Emergency Care Applied Research Network (PECARN) prediction rule for identifying febrile infants 28 days or younger with bacteremia or bacterial meningitis.\n\nDesign, setting, and participants — This pooled analysis of 4 published prospective cohort studies from pediatric emergency departments across 6 countries within the global Pediatric Emergency Research Network included previously healthy, non-ill-appearing, full-term (≥37 weeks' gestation) infants aged 28 days or younger with a temperature greater than or equal to 38.0 °C who underwent urine, blood, and serum testing.\n\nExposure — Infants were classified as low risk if they had a negative urinalysis/dipstick test result, serum procalcitonin less than or equal to 0.5 ng/mL, and blood absolute neutrophil count less than or equal to 4000/mm3.\n\nMain outcomes and measures — Meta-analytic methods were applied to assess diagnostic accuracy (sensitivity, specificity, and positive and negative predictive values) of the PECARN rule for detection of infants with invasive bacterial infections (bacteremia or bacterial meningitis).\n\nResults — Among 1537 infants 28 days or younger (905 male, 1324 hospitalized, 1080 with lumbar punctures), 69 (4.5%) had invasive bacterial infections, including 11 (0.7%) with bacterial meningitis. Overall, 632 (41.1%) met low-risk criteria. The prediction rule had a sensitivity of 94.2% (95% CI, 85.6%-97.8%), specificity of 41.6% (95% CI, 36.7%-46.7%), positive predictive value of 6.9% (95% CI, 4.8%-9.9%), and negative predictive value of 99.4% (95% CI, 98.1%-99.8%) for invasive bacterial infections. In a secondary analysis of 2531 infants from the 2 US-based cohorts from which the rule was originally derived and the 4 validation cohorts, 96 (3.8%) had invasive bacterial infections, 22 (0.9%) had bacterial meningitis, and 1079 (42.6%) were classified as low risk; rule performance was similar. No infants with bacterial meningitis were misclassified in the primary or secondary analyses.\n\nConclusions and relevance — The updated PECARN rule had high sensitivity but lower specificity for identifying febrile infants 28 days or younger with invasive bacterial infections in this study, with no missed cases of bacterial meningitis. These results may support shared decision-making regarding select vs routine use of lumbar puncture among infants classified as being at low risk of invasive bacterial infections.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41359314/", "doi_url": "https://doi.org/10.1001/jama.2025.21454", "pmc_url": "https://europepmc.org/article/PMC/PMC12687207", "article_url": "https://doi.org/10.1001/jama.2025.21454"}, {"id": "pmid-41314221", "pmid": "41314221", "pmcid": "", "doi": "10.1016/s1473-3099(25)00619-x", "title": "Empirical and targeted antimicrobial therapy in patients with febrile neutropenia and haematological malignancy or after haematopoietic cell transplantation: recommendations from the 10th European Conference on Infections in Leukaemia", "title_fr": "Neutropénie fébrile en hématologie : les recommandations ECIL-10 sur l'antibiothérapie", "authors_list": ["Averbuch D", "Vanbiervliet Y", "Baccelli F", "Mikulska M", "Neofytos D", "Garcia-Vidal C", "Aguilar-Guisado M", "Blijlevens N", "Munoz P", "Cordonnier C", "Akova M", "Calandra T"], "authors_short": "Averbuch D et al.", "journal": "The Lancet Infectious Diseases", "journal_short": "Lancet Infect Dis", "year": 2025, "month_num": 11, "pub_date": "2025-11-25", "pub_date_fr": "novembre 2025", "volume": "26", "issue": "6", "pages": "e232-e247", "pub_types": ["Review", "Journal Article"], "category_id": "immunodeprimes", "category_label": "Immunodéprimés & fongiques", "category_color": "#6d28d9", "audience": "Enfant & adulte", "study_fr": "Recommandations ECIL-10 · Lancet Infectious Diseases", "design": "Recommandations", "impact_factor": 31.0, "summary_fr": "La 10e Conférence européenne sur les infections en leucémie propose une approche personnalisée de la neutropénie fébrile, guidée par l'écologie locale et les facteurs de risque individuels. Chez le patient stable, sans colonisation à BGN résistant et en zone de faible résistance, une monothérapie épargnant les carbapénèmes est recommandée. Une désescalade puis un arrêt des antibiotiques sont possibles même si les neutrophiles restent bas.", "key_points_fr": ["Patient stable, non colonisé, faible prévalence de résistance : monothérapie sans carbapénème.", "Patient instable, colonisé ou en zone de forte résistance : spectre élargi d'emblée.", "Désescalade dès qu'une infection à BGN résistant est exclue.", "Arrêt possible chez le patient apyrétique et stable, quel que soit le taux de neutrophiles."], "pratique_fr": "Ces recommandations encouragent l'épargne des carbapénèmes et l'arrêt des antibiotiques avant la sortie d'aplasie, y compris dans les services d'onco-hématologie pédiatrique.", "tags": ["Neutropénie fébrile", "ECIL", "Onco-hématologie", "BGN résistants", "Désescalade"], "abstract_en": "Febrile neutropenia can lead to life-threatening infections in patients with haematological malignancies or after hematopoietic cell transplantation. Infection management is challenged by rising antibiotic resistance and regional differences in bacterial epidemiology. The 10th European Conference on Infections in Leukaemia panel recommends a personalised approach guided by local resistance patterns and individual risk factors. For patients who are haemodynamically stable without colonisation or infection by resistant Gram-negative bacteria in low-resistance prevalence settings, empirical monotherapy sparing carbapenems or novel β-lactams with or without β-lactamase inhibitors (BLI) is recommended. For patients who are critically ill or haemodynamically unstable, those with previous resistant Gram-negative bacteria colonisation or infection, or in high-resistance prevalence settings, broader-spectrum therapy is indicated. Treatment options include β-lactam plus aminoglycoside combinations, carbapenem with or without BLI, anti-pseudomonal cephalosporin and BLI combinations, or cefiderocol, individualised by local epidemiology and patient factors. Antimicrobial stewardship is recommended, including antimicrobial de-escalation once resistant Gram-negative bacteria infection is excluded; and antibiotic discontinuation regardless of neutrophil count, in patients who are afebrile and stable after completing the intended course. We provide treatment strategies for resistant Gram-negative bacteria infections.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41314221/", "doi_url": "https://doi.org/10.1016/s1473-3099(25)00619-x", "pmc_url": "", "article_url": "https://doi.org/10.1016/s1473-3099(25)00619-x"}, {"id": "pmid-41115439", "pmid": "41115439", "pmcid": "", "doi": "10.1016/s0140-6736(25)01624-1", "title": "Cloxacillin versus cefazolin for meticillin-susceptible Staphylococcus aureus bacteraemia (CloCeBa): a prospective, open-label, multicentre, non-inferiority, randomised clinical trial", "title_fr": "CloCeBa : l'essai français qui valide la céfazoline dans les bactériémies à SAMS", "authors_list": ["Burdet C", "Saïdani N", "Dupieux C", "Lemaignen A", "Canouï E", "Surgers L", "Vareil MO", "Lefort A", "Lepeule R", "Peiffer-Smadja N", "Charmillon A", "Le Moing V", "Boutoille D", "Tolsma V", "Abgrall S", "Wolff M", "Tattevin P", "Esposito-Farèse M", "Vandenesch F", "Duval X", "Tubiana S", "Lescure FX", "CloCeBa Study Group"], "authors_short": "Burdet C et al.", "journal": "The Lancet", "journal_short": "Lancet", "year": 2025, "month_num": 10, "pub_date": "2025-10-17", "pub_date_fr": "octobre 2025", "volume": "406", "issue": "10517", "pages": "2349-2359", "pub_types": ["Comparative Study", "Equivalence Trial", "Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "adulte", "category_label": "Infectiologie adulte", "category_color": "#334155", "audience": "Adulte", "study_fr": "Essai randomisé de non-infériorité · 21 hôpitaux français · 315 patients", "design": "Essai randomisé", "impact_factor": 88.5, "summary_fr": "Premier essai randomisé comparant céfazoline et cloxacilline pendant les 7 premiers jours de traitement d'une bactériémie à SAMS, hors matériel intravasculaire et infection neuroméningée. Le succès à J90 est identique (75 % vs 74 %) et la céfazoline entraîne moins d'événements indésirables graves et beaucoup moins d'insuffisance rénale aiguë.", "key_points_fr": ["Critère composite : 75 % (céfazoline) vs 74 % (cloxacilline), non-infériorité démontrée.", "Événements indésirables graves : 15 % vs 27 % (p = 0,010).", "Insuffisance rénale aiguë : 1 % vs 12 % (p = 0,0002).", "Exclusion des infections du système nerveux central et des implants intravasculaires."], "pratique_fr": "La céfazoline, plus simple à administrer (toutes les 8 h) et mieux tolérée, est une alternative validée à la cloxacilline.", "tags": ["Staphylococcus aureus", "Bactériémie", "Céfazoline", "Cloxacilline", "Essai français"], "abstract_en": "Background — Although widely used, cefazolin efficacy for the treatment of meticillin-susceptible Staphylococcus aureus (MSSA) bacteraemia has not thus far been investigated in a clinical trial. In this study, we aimed to compare the efficacy and safety of cefazolin with that of cloxacillin in patients with MSSA bacteraemia.\n\nMethods — We conducted an open-label, non-inferiority, randomised clinical trial in 21 university and non-university hospitals in France in adults (aged ≥18 years) with MSSA bacteraemia, without intravascular implant or suspicion of CNS infection. Participants were randomly assigned (1:1) to receive intravenously cefazolin (25-50 mg/kg every 8 h) or cloxacillin (25-50 mg/kg every 4-6 h) for the first 7 days of therapy using computer-generated blocks of various sizes and stratification on vascular-access associated bacteraemia and centre. Subsequent treatment was left to the choice of the investigator (total duration ≥14 days). The primary endpoint was a composite of sterile blood cultures at day 3 (day 5 for endocarditis) without relapse of bacteraemia, survival, and clinical success at day 90, and was assessed in the intention-to-treat population. A non-inferiority margin of 12% was chosen. This trial is registered on ClinicalTrials.gov (NCT03248063) and is complete.\n\nFindings — Between Sept 5, 2018, and Nov 16, 2023, 315 participants were enrolled and assigned to cefazolin (n=158) or cloxacillin (n=157); 12 participants were excluded from analysis in the cefazolin group, and 11 in the cloxacillin group (final population of 146 in each group). Mean age was 62·7 years (SD 16·4), 215 (74%) participants were male, and race or ethnicity data were not collected. Median Pitt score was 0 (IQR 0-0). The primary endpoint was met in 109 (75%) of 146 participants in the cefazolin group versus 108 (74%) of 146 participants in the cloxacillin group (treatment difference -1%; 95% CI -11 to 9; p=0·012). At the end of study treatment, 22 (15%) of 146 participants assigned to cefazolin and 40 (27%) of 146 participants assigned to cloxacillin had had a serious adverse event (p=0·010). Acute kidney injury occurred more frequently in participants assigned to cloxacillin (15 [12%] of 128) than in those assigned to cefazolin (one [1%] of 134; p=0·0002).\n\nInterpretation — Cefazolin constitutes an alternative to cloxacillin for the treatment of MSSA bacteraemia, offering non-inferior clinical efficacy and potentially enhanced tolerability.\n\nFunding — French Ministry of Health.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/41115439/", "doi_url": "https://doi.org/10.1016/s0140-6736(25)01624-1", "pmc_url": "", "article_url": "https://doi.org/10.1016/s0140-6736(25)01624-1"}, {"id": "pmid-40961446", "pmid": "40961446", "pmcid": "", "doi": "10.1056/nejmoa2502984", "title": "Clesrovimab for Prevention of RSV Disease in Healthy Infants", "title_fr": "Clesrovimab : un nouvel anticorps monoclonal anti-VRS en dose unique", "authors_list": ["Zar HJ", "Simões EAF", "Madhi SA", "Ramilo O", "Senders SD", "Shepard JS", "Laoprasopwattana K", "Piedrahita J", "Novoa JM", "Vargas SL", "Dionne M", "Jackowska T", "Liu E", "Ishihara Y", "Ikeda K", "Zhang Y", "Railkar RA", "Lutkiewicz J", "Vora KA", "Zang X", "Maas BM", "Lee AW", "Guerra A", "Sinha A", "CLEVER (MK-1654-004) Study Group"], "authors_short": "Zar HJ et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2025, "month_num": 9, "pub_date": "2025-09-17", "pub_date_fr": "septembre 2025", "volume": "393", "issue": "13", "pages": "1292-1303", "pub_types": ["Clinical Trial, Phase III", "Clinical Trial, Phase II", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "vaccins", "category_label": "Vaccins & infections communautaires", "category_color": "#0f766e", "audience": "Enfant", "study_fr": "Essai de phase 2b/3 randomisé contre placebo (CLEVER) · 3 614 nourrissons", "design": "Essai randomisé", "impact_factor": 78.5, "summary_fr": "Le clesrovimab, anticorps à longue durée d'action dirigé contre le site IV de la protéine F du VRS, a été administré en une injection unique de 105 mg chez des nourrissons prématurés et à terme. Il réduit de 60 % les infections respiratoires basses à VRS ayant nécessité une consultation au cours des 150 jours suivants, et réduit aussi les hospitalisations, avec une tolérance comparable au placebo.", "key_points_fr": ["Randomisation 2:1, dose fixe de 105 mg IM quel que soit le poids.", "Incidence sur 5 mois : 2,6 % sous clesrovimab vs 6,5 % sous placebo (efficacité 60,4 %).", "Réduction également des hospitalisations liées au VRS (critère secondaire clé).", "Profil de sécurité similaire au placebo."], "pratique_fr": "Une alternative au nirsévimab se profile ; son intérêt réel dépendra des comparaisons directes et des recommandations françaises à venir.", "tags": ["VRS", "Clesrovimab", "Anticorps monoclonal", "Prévention"], "abstract_en": "Background — Clesrovimab is a long-acting investigational monoclonal antibody against site IV of the respiratory syncytial virus (RSV) fusion protein. Data regarding the safety and efficacy of clesrovimab in healthy infants are needed.\n\nMethods — We randomly assigned healthy preterm and full-term infants entering their first RSV season in a 2:1 ratio to receive one intramuscular 105-mg dose of clesrovimab or placebo. The primary efficacy end point was RSV-associated medically attended lower respiratory infection (including at least one indicator of lower respiratory infection or disease severity) through 150 days after injection. A key secondary efficacy end point was RSV-associated hospitalization during the same period.\n\nResults — A total of 3614 infants received an injection: 2412 infants received clesrovimab, and 1202 infants received placebo. Through day 150 after injection, RSV-associated medically attended lower respiratory infection occurred in 60 of 2398 infants in the clesrovimab group (incidence rate over 5-month period, 2.6%) and in 74 of 1201 infants in the placebo group (incidence rate over 5-month period, 6.5%), for an efficacy of 60.4% (95% confidence interval [CI], 44.1 to 71.9; P<0.001). RSV-associated hospitalization within 150 days was reported in 9 of 2398 infants in the clesrovimab group and in 28 of 1201 infants in the placebo group, for an efficacy of 84.2% (95% CI, 66.6 to 92.6; P<0.001). Serious adverse events were reported in 278 of 2409 infants (11.5%) in the clesrovimab group and 149 of 1202 infants (12.4%) in the placebo group.\n\nConclusions — In healthy preterm and full-term infants, a single dose of clesrovimab reduced the incidence of RSV-associated medically attended lower respiratory infection and RSV-associated hospitalization, with a safety profile similar to that of placebo. (Funded by Merck Sharp and Dohme; CLEVER ClinicalTrials.gov number, NCT04767373.).", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40961446/", "doi_url": "https://doi.org/10.1056/nejmoa2502984", "pmc_url": "", "article_url": "https://doi.org/10.1056/nejmoa2502984"}, {"id": "pmid-40802264", "pmid": "40802264", "pmcid": "PMC12351474", "doi": "10.1001/jama.2025.12543", "title": "Dalbavancin for Treatment of Staphylococcus aureus Bacteremia: The DOTS Randomized Clinical Trial", "title_fr": "DOTS : la dalbavancine pour terminer le traitement des bactériémies compliquées à S. aureus", "authors_list": ["Turner NA", "Hamasaki T", "Doernberg SB", "Lodise TP", "King HA", "Ghazaryan V", "Cosgrove SE", "Jenkins TC", "Liu C", "Sharma S", "Zaharoff S", "Wahid L", "Renard VJ", "Cook P", "Raad I", "Hachem R", "Chaftari AM", "Sims M", "DeMarco C", "Miller LG", "McCarthy MW", "Morse CG", "Lucasti C", "Forrest GN", "Cherabuddi K", "Polk C", "Fazili T", "Rupp ME", "Thompson GR 3rd", "Kim K", "Strnad L", "Schnee AE", "McKinnell JA", "Ramesh M", "Silveira FP", "McCarty TP", "Lee TC", "McDonald EG", "Paolino K", "Wiegand K", "Wall A", "Riccobene T", "Patel R", "Rappo U", "Evans S", "Chambers HF", "Fowler VG Jr", "Holland TL", "Antibacterial Resistance Leadership Group"], "authors_short": "Turner NA et al.", "journal": "JAMA", "journal_short": "JAMA", "year": 2025, "month_num": 8, "pub_date": "2025-08-13", "pub_date_fr": "août 2025", "volume": "", "issue": "", "pages": "", "pub_types": ["research-article", "Journal Article"], "category_id": "adulte", "category_label": "Infectiologie adulte", "category_color": "#334155", "audience": "Adulte", "study_fr": "Essai randomisé ouvert, évaluateur en aveugle · 23 centres · 200 patients", "design": "Essai randomisé", "impact_factor": 55.0, "summary_fr": "Chez des adultes avec une bactériémie compliquée à S. aureus et des hémocultures négativées, deux doses de dalbavancine (1 500 mg à J1 et J8) ont été comparées à 4 à 8 semaines de traitement IV standard. La dalbavancine n'est pas supérieure sur le classement DOOR, mais son efficacité clinique est non inférieure (73 % vs 72 %), sans cathéter de longue durée.", "key_points_fr": ["Probabilité d'un meilleur résultat DOOR avec la dalbavancine : 47,7 %, donc pas de supériorité.", "Efficacité clinique à J70 : 73 % vs 72 %, non-infériorité atteinte.", "Événements indésirables graves : 40 % vs 34 % ; effets liés au traitement rares.", "Exclusions : endocardite gauche, matériel infecté, atteinte neurologique, immunodépression sévère."], "pratique_fr": "Une option pour éviter une voie veineuse prolongée chez certains patients, après négativation des hémocultures.", "tags": ["Staphylococcus aureus", "Bactériémie", "Dalbavancine", "Ostéomyélite", "OPAT"], "abstract_en": "Importance — Dalbavancin is a long-acting intravenous lipoglycopeptide that may be effective for treatment of complicated Staphylococcus aureus bacteremia without requiring long-term intravenous access.\n\nObjective — To evaluate the efficacy and safety of dalbavancin vs standard therapy for completion of treatment of complicated S aureus bacteremia.\n\nDesign, setting, and participants — Open-label, assessor-masked, randomized clinical trial conducted from April 2021 to December 2023 at 23 medical centers in the US (n = 22) and Canada (n = 1). Participant follow-up lasted 70 days (180 days for participants with osteomyelitis); date of final follow-up was December 1, 2023. Hospitalized adults with complicated S aureus bacteremia who achieved blood culture clearance following at least 72 hours but no more than 10 days of initial antibacterial therapy were included. Participants were excluded if they had central nervous system infection, retained infected prosthetic material, left-sided endocarditis, or severe immune compromise.\n\nInterventions — Participants were randomly assigned to receive either 2 doses of intravenous dalbavancin (n = 100; 1500 mg on days 1 and 8) or 4 to 8 total weeks of standard intravenous therapy (n = 100; cefazolin or antistaphylococcal penicillin if methicillin susceptible; vancomycin or daptomycin if methicillin resistant).\n\nMain outcomes and measures — The primary outcome was the desirability of outcome ranking (DOOR) at day 70, which involved 5 components (clinical success, infectious complications, safety complications, mortality, and health-related quality of life) and was assessed for superiority (achieved if the 95% CI for the probability of dalbavancin having a superior DOOR was >50%). Secondary outcomes included clinical efficacy at day 70 (prespecified noninferiority margin of 20%) and safety.\n\nResults — Of 200 participants randomized (mean [SD] age, 56 [16.2] years; 62 females [31%]), 167 (84%) survived to day 70 and had an efficacy assessment. Participants without a day 70 efficacy assessment were treated as clinical failures in the analyses. The probability of a more desirable day 70 outcome with dalbavancin vs standard therapy was 47.7% (95% CI, 39.8% to 55.7%). Regarding secondary outcomes, clinical efficacy was documented in 73 of 100 for dalbavancin and 72 of 100 for standard therapy (difference, 1.0% [95% CI, -11.5% to 13.5%]), meeting the noninferiority criterion. Serious adverse events were reported in 40 of 100 participants who received dalbavancin and 34 of 100 participants who received standard therapy; treatment-related adverse events were uncommon in both groups.\n\nConclusions and relevance — Among adult participants with complicated S aureus bacteremia who achieved blood culture clearance, dalbavancin was not superior to standard therapy by desirability of outcome ranking. When considered with other efficacy and safety outcomes these findings may help inform use of dalbavancin in clinical practice.\n\nTrial registration — ClinicalTrials.gov Identifier: NCT04775953.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40802264/", "doi_url": "https://doi.org/10.1001/jama.2025.12543", "pmc_url": "https://europepmc.org/article/PMC/PMC12351474", "article_url": "https://doi.org/10.1001/jama.2025.12543"}, {"id": "pmid-40216161", "pmid": "40216161", "pmcid": "", "doi": "10.1016/j.idnow.2025.105062", "title": "The latest updates on the proper use of fluoroquinolones - Actualisation 2025 update by the SPILF and the GPIP", "title_fr": "Bon usage des fluoroquinolones : l'actualisation 2025 de la SPILF et du GPIP", "authors_list": ["Vuotto F", "Bru JP", "Canoui E", "Caseris M", "Chopin MCC", "Cohen R", "Diamantis S", "Dinh A", "Fillatre P", "Gauzit R", "Gillet Y", "Jonville-Bera AP", "Lafaurie M", "Lesprit P", "Lorrot M", "Lourtet J", "Maulin L", "Poitrenaud D", "Pariente A", "Raymond J", "Strady C", "Stahl JP", "Varon E", "Welker Y", "Bonnet E"], "authors_short": "Vuotto F et al.", "journal": "Infectious Diseases Now", "journal_short": "Infect Dis Now", "year": 2025, "month_num": 4, "pub_date": "2025-04-10", "pub_date_fr": "avril 2025", "volume": "55", "issue": "4", "pages": "105062", "pub_types": ["Practice Guideline", "Journal Article"], "category_id": "antiinfectieux", "category_label": "Anti-infectieux & antibioprophylaxie", "category_color": "#047857", "audience": "Enfant & adulte", "study_fr": "Recommandations françaises SPILF & GPIP · Infectious Diseases Now", "design": "Recommandations", "impact_factor": 2.2, "summary_fr": "La SPILF et le GPIP actualisent conjointement les règles de bon usage des fluoroquinolones chez l'adulte et chez l'enfant. Ce texte, sans résumé sur PubMed, précise les situations où ces molécules gardent leur place, celles où elles doivent être évitées compte tenu de leurs effets indésirables et du risque de résistance, ainsi que les spécificités pédiatriques.", "key_points_fr": ["Texte conjoint adulte et pédiatrie (SPILF + GPIP).", "Remet à jour les indications réservées des fluoroquinolones.", "Intègre les alertes de pharmacovigilance sur les effets indésirables graves.", "Pas d'abstract PubMed : lire le texte intégral pour les schémas détaillés."], "pratique_fr": "La référence française pour justifier, ou éviter, une prescription de fluoroquinolone, y compris chez l'enfant.", "tags": ["Fluoroquinolones", "SPILF", "GPIP", "Bon usage", "Recommandations françaises"], "abstract_en": "", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40216161/", "doi_url": "https://doi.org/10.1016/j.idnow.2025.105062", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.idnow.2025.105062"}, {"id": "pmid-40463685", "pmid": "40463685", "pmcid": "PMC12132041", "doi": "10.5194/jbji-10-101-2025", "title": "Debridement, antimicrobial therapy, and implant retention (DAIR) as curative strategy for acute periprosthetic hip and knee infections: a position paper of the European Bone & Joint Infection Society (EBJIS)", "title_fr": "DAIR dans l'infection aiguë de prothèse de hanche et de genou : la position de l'EBJIS", "authors_list": ["Sigmund IK", "Ferry T", "Sousa R", "Soriano A", "Metsemakers WJ", "Clauss M", "Trebse R", "Wouthuyzen-Bakker M"], "authors_short": "Sigmund IK et al.", "journal": "Journal of Bone and Joint Infection", "journal_short": "J Bone Jt Infect", "year": 2025, "month_num": 4, "pub_date": "2025-04-01", "pub_date_fr": "avril 2025", "volume": "10", "issue": "2", "pages": "101-138", "pub_types": ["other", "Journal Article"], "category_id": "ioa", "category_label": "Infections ostéo-articulaires", "category_color": "#a16207", "audience": "Adulte", "study_fr": "Position paper · European Bone & Joint Infection Society", "design": "Position d'experts", "impact_factor": 2.7, "summary_fr": "Le succès d'un DAIR (débridement, antibiothérapie et conservation de l'implant) dépend du type d'infection, du terrain, de l'état des parties molles, du germe, de la technique chirurgicale et de l'antibiothérapie. L'EBJIS définit les indications, contre-indications et facteurs de risque d'échec, et détaille la technique chirurgicale associée à l'antibiothérapie systémique.", "key_points_fr": ["La sélection des patients est la clé du succès du DAIR.", "Indications et contre-indications fondées sur les données les plus récentes.", "Le geste chirurgical et l'antibiothérapie doivent être pensés ensemble.", "Une équipe multidisciplinaire dédiée améliore les résultats."], "pratique_fr": "Une référence pour discuter en RCP de l'option DAIR face à une infection aiguë de prothèse plutôt que d'un changement en un ou deux temps.", "tags": ["Infection de prothèse", "DAIR", "EBJIS", "Chirurgie orthopédique"], "abstract_en": "It has been shown that the outcome of a DAIR (debridement, antimicrobial therapy, and implant retention) procedure depends on multiple factors (e.g. infection type, host factors, clinical presentation, condition of surrounding soft tissue, causing pathogen, surgical technique, antimicrobial therapy); therefore, adequate patient selection is key for DAIR success. In this position paper, we discuss the most relevant factors influencing the outcome and define indications, contraindications, and risk factors for a DAIR procedure based on the most robust and most recently published data. Furthermore, we discuss the surgical technique in combination with systemic antimicrobial therapy in patients undergoing a DAIR procedure. This position paper may help reduce reinfection rates as well as the physical, psychological, and economic burden associated with periprosthetic joint infection (PJI). We believe that a reasonable outcome can be achieved with careful patient selection, a dedicated multidisciplinary team, and an appropriate surgical technique and antimicrobial therapy.", "reading_min": 2, "pdf_file": "pdfs/PMID_40463685.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40463685/", "doi_url": "https://doi.org/10.5194/jbji-10-101-2025", "pmc_url": "https://europepmc.org/article/PMC/PMC12132041", "article_url": "https://doi.org/10.5194/jbji-10-101-2025"}, {"id": "pmid-40011104", "pmid": "40011104", "pmcid": "", "doi": "10.1016/j.idnow.2025.105034", "title": "Update of guidelines for management of community acquired pneumonia in adults by the French infectious disease society (SPILF) and the French-speaking society of respiratory diseases (SPLF). Endorsed by the French intensive care society (SRLF), the French microbiology society (SFM), the French radiology society (SFR) and the French emergency society (SFMU)", "title_fr": "Pneumonie aiguë communautaire de l'adulte : l'actualisation SPILF / SPLF 2025", "authors_list": ["Dinh A", "Barbier F", "Bedos JP", "Blot M", "Cattoir V", "Claessens YE", "Duval X", "Fillâtre P", "Gautier M", "Guegan Y", "Jarraud S", "Monnier AL", "Lebeaux D", "Loubet P", "de Margerie C", "Serayet P", "Tandjaoui-Lambotte Y", "Varon E", "Welker Y", "Basille D"], "authors_short": "Dinh A et al.", "journal": "Infectious Diseases Now", "journal_short": "Infect Dis Now", "year": 2025, "month_num": 2, "pub_date": "2025-02-25", "pub_date_fr": "février 2025", "volume": "55", "issue": "2", "pages": "105034", "pub_types": ["Practice Guideline", "Journal Article"], "category_id": "adulte", "category_label": "Infectiologie adulte", "category_color": "#334155", "audience": "Adulte", "study_fr": "Recommandations françaises SPILF & SPLF, avec SRLF, SFM, SFR et SFMU", "design": "Recommandations", "impact_factor": 2.2, "summary_fr": "La SPILF et la SPLF actualisent la prise en charge de la pneumonie aiguë communautaire de l'adulte, avec l'aval des sociétés françaises de réanimation, microbiologie, radiologie et médecine d'urgence. Le texte, sans résumé sur PubMed, couvre le diagnostic, la place de l'imagerie et de la microbiologie, l'antibiothérapie probabiliste, sa durée et les traitements adjuvants.", "key_points_fr": ["Texte multidisciplinaire endossé par six sociétés savantes françaises.", "Actualise le choix et la durée de l'antibiothérapie probabiliste.", "Précise la place de l'imagerie et des examens microbiologiques.", "Pas d'abstract PubMed : lire le texte intégral pour les schémas détaillés."], "pratique_fr": "La référence française actuelle pour la pneumonie de l'adulte, utile aussi pour les adolescents et la transition.", "tags": ["Pneumonie communautaire", "SPILF", "SPLF", "Recommandations françaises"], "abstract_en": "", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/40011104/", "doi_url": "https://doi.org/10.1016/j.idnow.2025.105034", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.idnow.2025.105034"}, {"id": "pmid-39956121", "pmid": "39956121", "pmcid": "", "doi": "10.1016/s1473-3099(24)00749-7", "title": "Global guideline for the diagnosis and management of candidiasis: an initiative of the ECMM in cooperation with ISHAM and ASM", "title_fr": "Candidoses : les nouvelles recommandations mondiales ECMM / ISHAM / ASM", "authors_list": ["Cornely OA", "Sprute R", "Bassetti M", "Chen SC", "Groll AH", "Kurzai O", "Lass-Flörl C", "Ostrosky-Zeichner L", "Rautemaa-Richardson R", "Revathi G", "Santolaya ME", "White PL", "Alastruey-Izquierdo A", "Arendrup MC", "Baddley J", "Barac A", "Ben-Ami R", "Brink AJ", "Grothe JH", "Guinea J", "Hagen F", "Hochhegger B", "Hoenigl M", "Husain S", "Jabeen K", "Jensen HE", "Kanj SS", "Koehler P", "Lehrnbecher T", "Lewis RE", "Meis JF", "Nguyen MH", "Pana ZD", "Rath PM", "Reinhold I", "Seidel D", "Takazono T", "Vinh DC", "Zhang SX", "Afeltra J", "Al-Hatmi AMS", "Arastehfar A", "Arikan-Akdagli S", "Bongomin F", "Carlesse F", "Chayakulkeeree M", "Chai LYA", "Chamani-Tabriz L", "Chiller T", "Chowdhary A", "Clancy CJ", "Colombo AL", "Cortegiani A", "Corzo Leon DE", "Drgona L", "Dudakova A", "Farooqi J", "Gago S", "Ilkit M", "Jenks JD", "Klimko N", "Krause R", "Kumar A", "Lagrou K", "Lionakis MS", "Lmimouni BE", "Mansour MK", "Meletiadis J", "Mellinghoff SC", "Mer M", "Mikulska M", "Montravers P", "Neoh CF", "Ozenci V", "Pagano L", "Pappas P", "Patterson TF", "Puerta-Alcalde P", "Rahimli L", "Rahn S", "Roilides E", "Rotstein C", "Ruegamer T", "Sabino R", "Salmanton-García J", "Schwartz IS", "Segal E", "Sidharthan N", "Singhal T", "Sinko J", "Soman R", "Spec A", "Steinmann J", "Stemler J", "Taj-Aldeen SJ", "Talento AF", "Thompson GR 3rd", "Toebben C", "Villanueva-Lozano H", "Wahyuningsih R", "Weinbergerová B", "Wiederhold N", "Willinger B", "Woo PCY", "Zhu LP"], "authors_short": "Cornely OA et al.", "journal": "The Lancet Infectious Diseases", "journal_short": "Lancet Infect Dis", "year": 2025, "month_num": 2, "pub_date": "2025-02-13", "pub_date_fr": "février 2025", "volume": "25", "issue": "5", "pages": "e280-e293", "pub_types": ["Practice Guideline", "Review", "Journal Article"], "category_id": "immunodeprimes", "category_label": "Immunodéprimés & fongiques", "category_color": "#6d28d9", "audience": "Enfant & adulte", "study_fr": "Recommandations internationales · Lancet Infectious Diseases", "design": "Recommandations", "impact_factor": 31.0, "summary_fr": "Ces recommandations mondiales couvrent l'ensemble des candidoses, des candidémies et candidoses invasives du patient immunodéprimé ou de réanimation jusqu'aux formes cutanéo-muqueuses. Elles intègrent les pathogènes émergents (Candida auris, C. parapsilosis résistant au fluconazole), les nouvelles molécules et la révision de la taxonomie des Candida.", "key_points_fr": ["Candida est la première cause d'infection fongique chez le patient hospitalisé.", "Pathogènes émergents : Candida auris (Candidozyma auris), C. parapsilosis résistant au fluconazole.", "La révision taxonomique renomme plusieurs espèces : attention aux comptes rendus de microbiologie.", "Synthèses détaillées des niveaux de preuve en annexe."], "pratique_fr": "Le texte de référence à garder sous la main pour toute candidémie, y compris chez l'enfant immunodéprimé ou en réanimation.", "tags": ["Candidose", "Candidémie", "Antifongiques", "Candida auris", "Recommandations"], "abstract_en": "Candida species are the predominant cause of fungal infections in patients treated in hospital, contributing substantially to morbidity and mortality. Candidaemia and other forms of invasive candidiasis primarily affect patients who are immunocompromised or critically ill. In contrast, mucocutaneous forms of candidiasis, such as oral thrush and vulvovaginal candidiasis, can occur in otherwise healthy individuals. Although mucocutaneous candidiasis is generally not life-threatening, it can cause considerable discomfort, recurrent infections, and complications, particularly in patients with underlying conditions such as diabetes or in those taking immunosuppressive therapies. The rise of difficult-to-treat Candida infections is driven by new host factors and antifungal resistance. Pathogens, such as Candida auris (Candidozyma auris) and fluconazole-resistant Candida parapsilosis, pose serious global health risks. Recent taxonomic revisions have reclassified several Candida spp, potentially causing confusion in clinical practice. Current management guidelines are limited in scope, with poor coverage of emerging pathogens and new treatment options. In this Review, we provide updated recommendations for managing Candida infections, with detailed evidence summaries available in the appendix.", "reading_min": 2, "pdf_file": "pdfs/PMID_39956121.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39956121/", "doi_url": "https://doi.org/10.1016/s1473-3099(24)00749-7", "pmc_url": "", "article_url": "https://doi.org/10.1016/s1473-3099(24)00749-7"}, {"id": "pmid-39798581", "pmid": "39798581", "pmcid": "", "doi": "10.1016/s2352-4642(24)00306-7", "title": "Procalcitonin-guided duration of antibiotic treatment in children hospitalised with confirmed or suspected bacterial infection in the UK (BATCH): a pragmatic, multicentre, open-label, two-arm, individually randomised, controlled trial", "title_fr": "BATCH : la procalcitonine ne raccourcit pas les antibiothérapies IV chez l'enfant hospitalisé", "authors_list": ["Waldron CA", "Pallmann P", "Schoenbuchner S", "Harris D", "Brookes-Howell L", "Mateus C", "Bernatoniene J", "Cathie K", "Faust SN", "Hinds L", "Hood K", "Huang C", "Jones S", "Kotecha S", "Nabwera HM", "Patel S", "Paulus SC", "Powell CVE", "Preston J", "Xiang H", "Thomas-Jones E", "Carrol ED", "BATCH Trial Team"], "authors_short": "Waldron CA et al.", "journal": "The Lancet Child & Adolescent Health", "journal_short": "Lancet Child Adolesc Health", "year": 2025, "month_num": 1, "pub_date": "2025-01-09", "pub_date_fr": "janvier 2025", "volume": "9", "issue": "2", "pages": "121-130", "pub_types": ["Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Pragmatic Clinical Trial", "Journal Article"], "category_id": "antiinfectieux", "category_label": "Anti-infectieux & antibioprophylaxie", "category_color": "#047857", "audience": "Enfant", "study_fr": "Essai randomisé pragmatique · 15 hôpitaux britanniques · 1 949 enfants", "design": "Essai randomisé", "impact_factor": 15.5, "summary_fr": "Chez des enfants hospitalisés sous antibiotiques IV pour une infection bactérienne suspectée ou confirmée, un algorithme guidé par la procalcitonine n'a pas réduit la durée d'antibiothérapie IV par rapport à la prise en charge habituelle (environ 96 h vs 100 h), avec une sécurité équivalente.", "key_points_fr": ["Durée médiane d'antibiotiques IV : 96,0 h (procalcitonine) vs 99,7 h (soins usuels).", "Critère de sécurité composite : 9 % dans les deux groupes.", "Enfants de 72 heures à 18 ans, antibiothérapie IV prévue de plus de 48 h.", "Les services avaient déjà des programmes de bon usage des antibiotiques efficaces."], "pratique_fr": "Là où le bon usage des antibiotiques est déjà bien organisé, ajouter un algorithme procalcitonine n'apporte pas de bénéfice supplémentaire.", "tags": ["Procalcitonine", "Bon usage des antibiotiques", "Durée d'antibiothérapie", "Biomarqueurs"], "abstract_en": "Background — Procalcitonin is a rapid response biomarker specific for bacterial infection, which is not routinely used in the UK National Health Service. We aimed to assess whether using a procalcitonin-guided algorithm would safely reduce the duration of antibiotic therapy compared with usual care, in which C-reactive protein is the commonly used biomarker.\n\nMethods — The BATCH trial was a pragmatic, multicentre, open-label, parallel, two-arm, individually randomised, controlled trial conducted in 15 hospitals in England and Wales. Children aged 72 h to 18 years who were admitted to hospital and were being treated with intravenous antibiotics for suspected or confirmed bacterial infection and who were expected to remain on intravenous antibiotics for more than 48 h were enrolled. Participants were randomly assigned (1:1) to receive either current clinical management alone (usual care group) or clinical management with the addition of a procalcitonin test guided algorithm (procalcitonin group). Participants were randomly assigned by minimisation, with site and age group (0-6 months, 6 months to 2 years, 2-5 years, and older than 5 years) as minimisation factors and a random element to reduce predictability. Participants were randomly assigned remotely using a secure 24 h web-based randomisation programme. The coprimary outcomes were duration of intravenous antibiotic use, assessed for superiority, and a composite safety measure, assessed for non-inferiority (non-inferiority margin 5%). The primary analysis sample for each coprimary endpoint included all randomly assigned participants with available outcome data. This trial is registered with the International Standard Randomised Controlled Trial Number registry, ISRCTN11369832.\n\nFindings — Between June 11, 2018, and Oct 12, 2022, 15 282 children were screened for eligibility, 1949 of whom were randomly assigned to receive procalcitonin-guided antibiotic therapy (n=977) or usual care (n=972). The median intravenous antibiotic duration was 96·0 h (IQR 59·5-155·5) in the procalcitonin group and 99·7 h (61·2-153·8) in the usual care group (hazard ratio 0·96 [95% CI 0·87-1·05]). 78 (9%) of 917 participants in the procalcitonin group and 85 (9%) of 904 participants in the usual care group had at least one event covered by the composite safety outcome measure (estimated adjusted risk difference -0·81% [95% CI upper bound 1·11]).\n\nInterpretation — In children with suspected or confirmed bacterial infection admitted to hospitals in England and Wales for intravenous antibiotic treatment of at least 48 h, the introduction of a procalcitonin-guided algorithm did not reduce duration of intravenous antibiotics treatment and is non-inferior to usual care for safety outcomes. Therefore, evidence does not support the use of procalcitonin-guided algorithms where robust effective paediatric antibiotic stewardship programmes are established.\n\nFunding — National Institute for Health and Care Research.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39798581/", "doi_url": "https://doi.org/10.1016/s2352-4642(24)00306-7", "pmc_url": "", "article_url": "https://doi.org/10.1016/s2352-4642(24)00306-7"}, {"id": "pmid-39826968", "pmid": "39826968", "pmcid": "", "doi": "10.1016/s0140-6736(24)02420-6", "title": "Appendicectomy versus antibiotics for acute uncomplicated appendicitis in children: an open-label, international, multicentre, randomised, non-inferiority trial", "title_fr": "Appendicite non compliquée de l'enfant : les antibiotiques seuls ne font pas aussi bien que l'appendicectomie", "authors_list": ["St Peter SD", "Noel-MacDonnell JR", "Hall NJ", "Eaton S", "Suominen JS", "Wester T", "Svensson JF", "Almström M", "Muenks EP", "Beaudin M", "Piché N", "Brindle M", "MacRobie A", "Keijzer R", "Engstrand Lilja H", "Kassa AM", "Jancelewicz T", "Butter A", "Davidson J", "Skarsgard E", "Te-Lu Y", "Nah S", "Willan AR", "Pierro A"], "authors_short": "St Peter SD et al.", "journal": "The Lancet", "journal_short": "Lancet", "year": 2025, "month_num": 1, "pub_date": "2025-01-01", "pub_date_fr": "janvier 2025", "volume": "405", "issue": "10474", "pages": "233-240", "pub_types": ["Comparative Study", "Equivalence Trial", "Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Pragmatic Clinical Trial", "Journal Article"], "category_id": "pediatrie", "category_label": "Pédiatrie générale", "category_color": "#c2410c", "audience": "Enfant", "study_fr": "Essai randomisé de non-infériorité · 11 hôpitaux pédiatriques · 936 enfants de 5 à 16 ans", "design": "Essai randomisé", "impact_factor": 88.5, "summary_fr": "Chez l'enfant suspect d'appendicite non perforée, le traitement antibiotique seul a été comparé à l'appendicectomie d'emblée. À 12 mois, l'échec du traitement est survenu chez 34 % des enfants traités par antibiotiques contre 7 % des opérés (essentiellement des appendicectomies blanches). Avec une marge de non-infériorité de 20 %, l'antibiothérapie seule est déclarée inférieure à la chirurgie.", "key_points_fr": ["Échec à 12 mois : 34 % (153/452) sous antibiotiques vs 7 % (28/394) après appendicectomie, différence 26,7 %.", "Dans le bras chirurgie, presque tous les « échecs » étaient des appendicectomies blanches.", "Aucun décès ni événement indésirable grave ; événements indésirables légers à modérés plus fréquents sous antibiotiques (RR 4,3).", "8 % des enfants du bras antibiotiques secondairement opérés avaient un appendice histologiquement normal."], "pratique_fr": "L'approche non opératoire reste une option discutable au cas par cas, mais il faut informer les familles qu'un enfant sur trois environ sera finalement opéré dans l'année.", "tags": ["Appendicite", "Antibiothérapie", "Chirurgie pédiatrique", "Non-infériorité"], "abstract_en": "Background — Support for the treatment of uncomplicated appendicitis with non-operative management rather than surgery has been increasing in the literature. We aimed to investigate whether treatment of uncomplicated appendicitis with antibiotics in children is inferior to appendicectomy by comparing failure rates for the two treatments.\n\nMethods — In this pragmatic, multicentre, parallel-group, unmasked, randomised, non-inferiority trial, children aged 5-16 years with suspected non-perforated appendicitis (based on clinical diagnosis with or without radiological diagnosis) were recruited from 11 children's hospitals in Canada, the USA, Finland, Sweden, and Singapore. Patients were randomly assigned (1:1) to the antibiotic or the appendicectomy group with an online stratified randomisation tool, with stratification by sex, institution, and duration of symptoms (≥48 h vs <48 h). The primary outcome was treatment failure within 1 year of random assignment. In the antibiotic group, failure was defined as removal of the appendix, and in the appendicectomy group, failure was defined as a normal appendix based on pathology. In both groups, failure was also defined as additional procedures related to appendicitis requiring general anaesthesia. Interim analysis was done to determine whether inferiority was to be declared at the halfway point. We used a non-inferiority design with a margin of 20%. All outcomes were assessed in participants with 12-month follow-up data. The trial was registered at ClinicalTrials.gov (NCT02687464).\n\nFindings — Between Jan 20, 2016, and Dec 3, 2021, 936 patients were enrolled and randomly assigned to appendicectomy (n=459) or antibiotics (n=477). At 12-month follow-up, primary outcome data were available for 846 (90%) patients. Treatment failure occurred in 153 (34%) of 452 patients in the antibiotic group, compared with 28 (7%) of 394 in the appendicectomy group (difference 26·7%, 90% CI 22·4-30·9). All but one patient meeting the definition for treatment failure with appendicectomy were those with negative appendicectomies. Of those who underwent appendicectomy in the antibiotic group, 13 (8%) had normal pathology. There were no deaths or serious adverse events in either group. The relative risk of having a mild-to-moderate adverse event in the antibiotic group compared with the appendicectomy group was 4·3 (95% CI 2·1-8·7; p<0·0001).\n\nInterpretation — Based on cumulative failure rates and a 20% non-inferiority margin, antibiotic management of non-perforated appendicitis was inferior to appendicectomy.\n\nFunding — None.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39826968/", "doi_url": "https://doi.org/10.1016/s0140-6736(24)02420-6", "pmc_url": "", "article_url": "https://doi.org/10.1016/s0140-6736(24)02420-6"}, {"id": "pmid-39565030", "pmid": "39565030", "pmcid": "", "doi": "10.1056/nejmoa2404991", "title": "Antibiotic Treatment for 7 versus 14 Days in Patients with Bloodstream Infections", "title_fr": "BALANCE : 7 jours d'antibiotiques suffisent pour la plupart des bactériémies", "authors_list": ["BALANCE Investigators, for the Canadian Critical Care Trials Group, the Association of Medical Microbiology and Infectious Disease Canada Clinical Research Network, the Australian and New Zealand Intensive Care Society Clinical Trials Group, and the Australasian Society for Infectious Diseases Clinical Research Network", "Daneman N", "Rishu A", "Pinto R", "Rogers BA", "Shehabi Y", "Parke R", "Cook D", "Arabi Y", "Muscedere J", "Reynolds S", "Hall R", "Dwivedi DB", "McArthur C", "McGuinness S", "Yahav D", "Coburn B", "Geagea A", "Das P", "Shin P", "Detsky M", "Morris A", "Fralick M", "Powis JE", "Kandel C", "Sligl W", "Bagshaw SM", "Singhal N", "Belley-Cote E", "Whitlock R", "Khwaja K", "Morpeth S", "Kazemi A", "Williams A", "MacFadden DR", "McIntyre L", "Tsang J", "Lamontagne F", "Carignan A", "Marshall J", "Friedrich JO", "Cirone R", "Downing M", "Graham C", "Davis J", "Duan E", "Neary J", "Evans G", "Alraddadi B", "Al Johani S", "Martin C", "Elsayed S", "Ball I", "Lauzier F", "Turgeon A", "Stelfox HT", "Conly J", "McDonald EG", "Lee TC", "Sullivan R", "Grant J", "Kagan I", "Young P", "Lawrence C", "O'Callaghan K", "Eustace M", "Choong K", "Aslanian P", "Buehner U", "Havey T", "Binnie A", "Prazak J", "Reeve B", "Litton E", "Lother S", "Kumar A", "Zarychanski R", "Hoffman T", "Paterson D", "Daley P", "Commons RJ", "Charbonney E", "Naud JF", "Roberts S", "Tiruvoipati R", "Gupta S", "Wood G", "Shum O", "Miyakis S", "Dodek P", "Kwok C", "Fowler RA", "The BALANCE Investigators, for the Canadian Critical Care Trials Group, the Association of Medical Microbiology and Infectious Disease Canada Clinical Research Network, the Australian and New Zealand Intensive Care Society Clinical Trials Group, and the Australasian Society for Infectious Diseases Clinical Research Network\n"], "authors_short": "BALANCE Investigators, for the Canadian Critical Care Trials Group, the Association of Medical Microbiology and Infectious Disease Canada Clinical Research Network, the Australian and New Zealand Intensive Care Society Clinical Trials Group, and the Australasian Society for Infectious Diseases Clinical Research Network et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2024, "month_num": 11, "pub_date": "2024-11-20", "pub_date_fr": "novembre 2024", "volume": "392", "issue": "11", "pages": "1065-1078", "pub_types": ["Comparative Study", "Equivalence Trial", "Multicenter Study", "Journal Article"], "category_id": "adulte", "category_label": "Infectiologie adulte", "category_color": "#334155", "audience": "Adulte", "study_fr": "Essai randomisé de non-infériorité · 74 hôpitaux · 7 pays · 3 608 patients", "design": "Essai randomisé", "impact_factor": 78.5, "summary_fr": "Chez des patients hospitalisés, dont plus de la moitié en réanimation, avec une bactériémie (principalement à BGN, hors S. aureus et immunodépression sévère), 7 jours d'antibiotiques sont non inférieurs à 14 jours sur la mortalité à 90 jours (14,5 % vs 16,1 %). Les résultats sont homogènes quels que soient le patient, le germe ou le foyer infectieux.", "key_points_fr": ["Mortalité à J90 : 14,5 % (7 jours) vs 16,1 % (14 jours), différence -1,6 point.", "55 % des patients en réanimation ; 75 % d'infections communautaires.", "Origines principales : urinaire (42 %), abdominale (19 %), pulmonaire (13 %).", "Exclusions : S. aureus, contaminants possibles, foyers nécessitant un traitement prolongé."], "pratique_fr": "Un essai majeur qui fait de 7 jours la durée standard des bactériémies non compliquées à BGN, y compris en réanimation.", "tags": ["Bactériémie", "Durée courte", "BGN", "Réanimation", "NEJM"], "abstract_en": "Background — Bloodstream infections are associated with substantial morbidity and mortality. Early, appropriate antibiotic therapy is important, but the duration of treatment is uncertain.\n\nMethods — In a multicenter, noninferiority trial, we randomly assigned hospitalized patients (including patients in the intensive care unit [ICU]) who had bloodstream infection to receive antibiotic treatment for 7 days or 14 days. Antibiotic selection, dosing, and route were at the discretion of the treating team. We excluded patients with severe immunosuppression, foci requiring prolonged treatment, single cultures with possible contaminants, or cultures yielding Staphylococcus aureus. The primary outcome was death from any cause by 90 days after diagnosis of the bloodstream infection, with a noninferiority margin of 4 percentage points.\n\nResults — Across 74 hospitals in seven countries, 3608 patients underwent randomization and were included in the intention-to-treat analysis; 1814 patients were assigned to 7 days of antibiotic treatment, and 1794 to 14 days. At enrollment, 55.0% of patients were in the ICU and 45.0% were on hospital wards. Infections were acquired in the community (75.4%), hospital wards (13.4%) and ICUs (11.2%). Bacteremia most commonly originated from the urinary tract (42.2%), abdomen (18.8%), lung (13.0%), vascular catheters (6.3%), and skin or soft tissue (5.2%). By 90 days, 261 patients (14.5%) receiving antibiotics for 7 days had died and 286 patients (16.1%) receiving antibiotics for 14 days had died (difference, -1.6 percentage points [95.7% confidence interval {CI}, -4.0 to 0.8]), which showed the noninferiority of the shorter treatment duration. Patients were treated for longer than the assigned duration in 23.1% of the patients in the 7-day group and in 10.7% of the patients in the 14-day group. A per-protocol analysis also showed noninferiority (difference, -2.0 percentage points [95% CI, -4.5 to 0.6]). These findings were generally consistent across secondary clinical outcomes and across prespecified subgroups defined according to patient, pathogen, and syndrome characteristics.\n\nConclusions — Among hospitalized patients with bloodstream infection, antibiotic treatment for 7 days was noninferior to treatment for 14 days. (Funded by the Canadian Institutes of Health Research and others; BALANCE ClinicalTrials.gov number, NCT03005145.).", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39565030/", "doi_url": "https://doi.org/10.1056/nejmoa2404991", "pmc_url": "", "article_url": "https://doi.org/10.1056/nejmoa2404991"}, {"id": "pmid-39540734", "pmid": "39540734", "pmcid": "PMC11642194", "doi": "10.1128/aac.00484-24", "title": "Safety, outcomes, and pharmacokinetics of isavuconazole as a treatment for invasive fungal diseases in pediatric patients: a non-comparative phase 2 trial", "title_fr": "Isavuconazole chez l'enfant : efficacité, tolérance et pharmacocinétique dans l'aspergillose et la mucormycose", "authors_list": ["Segers H", "Deville JG", "Muller WJ", "Manzanares A", "Desai A", "Neely M", "Bordon V", "Hanisch B", "Lassaletta A", "Fisher BT", "Autmizguine J", "Groll AH", "Sinnar S", "Croos-Dabrera R", "Engelhardt M", "Jones M", "Kovanda LL", "Arrieta AC"], "authors_short": "Segers H et al.", "journal": "Antimicrobial Agents and Chemotherapy", "journal_short": "Antimicrob Agents Chemother", "year": 2024, "month_num": 11, "pub_date": "2024-11-14", "pub_date_fr": "novembre 2024", "volume": "68", "issue": "12", "pages": "e0048424", "pub_types": ["Clinical Trial, Phase II", "Research Support, Non-U.S. Gov't", "research-article", "Multicenter Study", "Journal Article"], "category_id": "immunodeprimes", "category_label": "Immunodéprimés & fongiques", "category_color": "#6d28d9", "audience": "Enfant", "study_fr": "Essai de phase 2 ouvert, non comparatif · 10 centres · 31 enfants de 1 à 17 ans", "design": "Essai de phase 2", "impact_factor": null, "summary_fr": "Chez des enfants atteints d'aspergillose ou de mucormycose invasive (prouvée, probable ou possible), l'isavuconazole à 10 mg/kg/j de prodrogue (maximum 372 mg) a permis une réponse globale favorable chez 55 % des patients en fin de traitement, avec une mortalité à J42 de 6,5 %. L'exposition est comparable à celle de l'adulte ; une dose de 15 mg/kg pourrait être nécessaire avant 3 ans.", "key_points_fr": ["58 % des enfants avaient une hémopathie maligne sous-jacente.", "Réponse globale favorable : 54,8 % ; mortalité toutes causes à J42 : 6,5 %.", "Deux arrêts de traitement pour effet indésirable lié au médicament.", "La simulation suggère d'augmenter à 15 mg/kg chez les 1–3 ans."], "pratique_fr": "L'isavuconazole devient une option crédible chez l'enfant, avec moins d'interactions et une tolérance hépatique et visuelle souvent meilleure que le voriconazole.", "tags": ["Isavuconazole", "Aspergillose", "Mucormycose", "Antifongiques", "Pharmacocinétique"], "abstract_en": "Invasive aspergillosis (IA) and mucormycosis (IM) cause significant morbidity and mortality in immunocompromised and/or hospitalized patients. Isavuconazonium sulfate, a prodrug of the antifungal triazole isavuconazole, has been approved for treatment of IA and IM in adults; and was recently approved in children. This study describes the outcomes, safety, and pharmacokinetics of isavuconazole for the treatment of proven, probable, or possible IA or IM in children. In this phase 2, open-label, non-comparative study, patients aged 1 to <18 years with at least possible invasive mold disease were enrolled across 10 centers in the US, Spain, and Belgium from 2019 to 2022. Patients received 10 mg/kg isavuconazonium sulfate daily (maximum 372 mg; equivalent to 5.4 mg/kg or 200 mg isavuconazole) for up to 84 (IA) or 180 days (IM). Outcomes included rates of all-cause case fatality, overall response, treatment-emergent adverse events (TEAEs), and pharmacokinetics. Of 31 patients enrolled, 61.3% were 1-<12 years old; 58.1% had underlying hematologic malignancies. The successful overall response rate at the end of treatment was 54.8%. Day 42 all-cause case fatality was 6.5%; 93.5% experienced TEAEs, and two patients discontinued treatment due to drug-related TEAEs. Dosing at 10 mg/kg (maximum dose: 372 mg) met the pre-defined exposure threshold of above the 25th percentile for the area under the concentration-time curve (≥60 mg·h/L). Simulated doses of 15 mg/kg improved drug exposures in patients aged 1-<3 years. Isavuconazole was well tolerated in children, with exposure consistent with adult studies. Successful response was documented in 54.8% of patients.\n\nCLINICAL TRIALS — This study is registered at ClinicalTrials.gov as NCT03816176.", "reading_min": 2, "pdf_file": "pdfs/PMID_39540734.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39540734/", "doi_url": "https://doi.org/10.1128/aac.00484-24", "pmc_url": "https://europepmc.org/article/PMC/PMC11642194", "article_url": "https://doi.org/10.1128/aac.00484-24"}, {"id": "pmid-39092529", "pmid": "39092529", "pmcid": "PMC11295439", "doi": "10.2807/1560-7917.es.2024.29.31.2400459", "title": "Resurgence of Bordetella pertussis, including one macrolide-resistant isolate, France, 2024", "title_fr": "Résurgence de la coqueluche en France en 2024, avec un premier isolat résistant aux macrolides", "authors_list": ["Rodrigues C", "Bouchez V", "Soares A", "Trombert-Paolantoni S", "Aït El Belghiti F", "Cohen JF", "Armatys N", "Landier A", "Blanchot T", "Hervo M", "REMICOQ study group", "Toubiana J", "Brisse S"], "authors_short": "Rodrigues C et al.", "journal": "Eurosurveillance", "journal_short": "Euro Surveill", "year": 2024, "month_num": 8, "pub_date": "2024-08-01", "pub_date_fr": "août 2024", "volume": "29", "issue": "31", "pages": "", "pub_types": ["research-article", "Journal Article"], "category_id": "vaccins", "category_label": "Vaccins & infections communautaires", "category_color": "#0f766e", "audience": "Enfant & adulte", "study_fr": "Surveillance nationale (CNR) · Eurosurveillance", "design": "Surveillance", "impact_factor": 7.8, "summary_fr": "Après trois années d'incidence quasi nulle, la France a connu en 2024 une forte reprise de la coqueluche : 5 616 PCR positives entre janvier et mai, soit près d'un test sur quatre. Les souches séquencées produisent majoritairement la pertactine et FIM2, à la différence des années pré-COVID. Un isolat résistant aux macrolides a été identifié.", "key_points_fr": ["5 616 qPCR positives (24,9 %) sur les 5 premiers mois de 2024.", "66 isolats sur 67 produisent la pertactine, 56 produisent FIM2.", "Un isolat de génotype Bp-AgST4 résistant aux macrolides.", "La résurgence pourrait favoriser les souches exprimant FIM2 et pertactine."], "pratique_fr": "Penser à la coqueluche devant une toux prolongée, protéger les nourrissons (vaccination de la femme enceinte, cocooning) et documenter les échecs de macrolides.", "tags": ["Coqueluche", "Bordetella pertussis", "Épidémiologie", "Résistance aux macrolides", "France"], "abstract_en": "As other European countries, France is experiencing a resurgence of pertussis in 2024. Between 1 January and 31 May 2024, 5,616 (24.9%) positive Bordetella pertussis qPCR tests were identified, following a 3-year period of almost null incidence. Of 67 cultured and whole genome sequenced B. pertussis isolates, 66 produced pertactin and 56 produced FIM2, in contrast to pre-COVID-19 years. One isolate of genotype Bp-AgST4 was resistant to macrolides. Pertussis resurgence may favour isolates that produce FIM2 and pertactin.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/39092529/", "doi_url": "https://doi.org/10.2807/1560-7917.es.2024.29.31.2400459", "pmc_url": "https://europepmc.org/article/PMC/PMC11295439", "article_url": "https://doi.org/10.2807/1560-7917.es.2024.29.31.2400459"}, {"id": "pmid-38986058", "pmid": "38986058", "pmcid": "", "doi": "10.1056/nejmoa2314885", "title": "Nirsevimab and Hospitalization for RSV Bronchiolitis", "title_fr": "Nirsévimab en vie réelle en France : 83 % d'efficacité contre l'hospitalisation pour bronchiolite à VRS", "authors_list": ["Assad Z", "Romain AS", "Aupiais C", "Shum M", "Schrimpf C", "Lorrot M", "Corvol H", "Prevost B", "Ferrandiz C", "Giolito A", "Valtuille Z", "Bendavid M", "Cohen JF", "Toubiana J", "de Pontual L", "Delande CF", "Levy M", "See P", "Cohen R", "Levy C", "Angoulvant F", "Lenglart L", "Gits-Muselli M", "Biran V", "Diallo K", "Alemede O", "El Hebil MM", "Durrmeyer X", "Labouret G", "Casanovas N", "Hallak B", "Maréchal O", "Jung C", "Bréhin C", "Ouldali N"], "authors_short": "Assad Z et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2024, "month_num": 7, "pub_date": "2024-07-01", "pub_date_fr": "juillet 2024", "volume": "391", "issue": "2", "pages": "144-154", "pub_types": ["Research Support, Non-U.S. Gov't", "Multicenter Study", "Journal Article"], "category_id": "vaccins", "category_label": "Vaccins & infections communautaires", "category_color": "#0f766e", "audience": "Enfant", "study_fr": "Étude cas-témoins prospective multicentrique française · 1 035 nourrissons", "design": "Cas-témoins", "impact_factor": 78.5, "summary_fr": "Première évaluation en vie réelle du nirsévimab lors de la saison 2023-2024 en France. Chez les nourrissons de moins de 12 mois, l'efficacité ajustée contre l'hospitalisation pour bronchiolite à VRS atteint 83 %. La protection persiste pour les formes graves : 70 % contre l'admission en soins critiques et 67 % contre le recours à une assistance ventilatoire.", "key_points_fr": ["690 cas hospitalisés appariés à 345 témoins (âge médian environ 3 mois).", "8,7 % des cas vs 28,1 % des témoins avaient reçu le nirsévimab.", "Efficacité : 83,0 % (IC95 % 73,4–89,2) contre l'hospitalisation.", "69,6 % contre les soins critiques, 67,2 % contre la ventilation."], "pratique_fr": "Ces données françaises confortent l'immunisation systématique des nourrissons par nirsévimab avant ou pendant leur première saison de VRS.", "tags": ["VRS", "Nirsévimab", "Bronchiolite", "Vie réelle", "France"], "abstract_en": "Background — Respiratory syncytial virus (RSV) is the leading cause of bronchiolitis, resulting in 3 million hospitalizations each year worldwide. Nirsevimab is a monoclonal antibody against RSV that has an extended half-life. Its postlicensure real-world effectiveness against RSV-associated bronchiolitis is unclear.\n\nMethods — We conducted a prospective, multicenter, matched case-control study to analyze the effectiveness of nirsevimab therapy against hospitalization for RSV-associated bronchiolitis in infants younger than 12 months of age. Case patients were infants younger than 12 months of age who were hospitalized for RSV-associated bronchiolitis between October 15 and December 10, 2023. Control patients were infants with clinical visits to the same hospitals for conditions unrelated to RSV infection. Case patients were matched to control patients in a 2:1 ratio on the basis of age, date of hospital visit, and study center. We calculated the effectiveness of nirsevimab therapy against hospitalization for RSV-associated bronchiolitis (primary outcome) by means of a multivariate conditional logistic-regression model with adjustment for confounders. Several sensitivity analyses were performed.\n\nResults — The study included 1035 infants, of whom 690 were case patients (median age, 3.1 months; interquartile range, 1.8 to 5.3) and 345 were matched control patients (median age, 3.4 months; interquartile range, 1.6 to 5.6). Overall, 60 case patients (8.7%) and 97 control patients (28.1%) had received nirsevimab previously. The estimated adjusted effectiveness of nirsevimab therapy against hospitalization for RSV-associated bronchiolitis was 83.0% (95% confidence interval [CI], 73.4 to 89.2). Sensitivity analyses gave results similar to those of the primary analysis. The effectiveness of nirsevimab therapy against RSV-associated bronchiolitis resulting in critical care was 69.6% (95% CI, 42.9 to 83.8) (27 of 193 case patients [14.0%] vs. 47 of 146 matched control patients [32.2%]) and against RSV-associated bronchiolitis resulting in ventilatory support was 67.2% (95% CI, 38.6 to 82.5) (27 of 189 case patients [14.3%] vs. 46 of 151 matched control patients [30.5%]).\n\nConclusions — In a real-world setting, nirsevimab therapy was effective in reducing the risk of hospitalized RSV-associated bronchiolitis. (Funded by the National Agency for AIDS Research-Emerging Infectious Disease and others; ENVIE ClinicalTrials.gov number, NCT06030505.).", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38986058/", "doi_url": "https://doi.org/10.1056/nejmoa2314885", "pmc_url": "", "article_url": "https://doi.org/10.1056/nejmoa2314885"}, {"id": "pmid-38944044", "pmid": "38944044", "pmcid": "", "doi": "10.1016/s0140-6736(24)00495-1", "title": "Neonatal bacterial sepsis", "title_fr": "Le sepsis bactérien néonatal : la mise au point du Lancet", "authors_list": ["Strunk T", "Molloy EJ", "Mishra A", "Bhutta ZA"], "authors_short": "Strunk T et al.", "journal": "The Lancet", "journal_short": "Lancet", "year": 2024, "month_num": 6, "pub_date": "2024-06-26", "pub_date_fr": "juin 2024", "volume": "404", "issue": "10449", "pages": "277-293", "pub_types": ["Review", "Journal Article"], "category_id": "sepsis", "category_label": "Sepsis & réanimation", "category_color": "#b91c1c", "audience": "Enfant", "study_fr": "Revue (Seminar) · The Lancet", "design": "Revue", "impact_factor": 88.5, "summary_fr": "Le sepsis néonatal reste, avec la prématurité, responsable de près de la moitié des décès d'enfants de moins de 5 ans dans le monde. Contrairement à l'adulte, il n'existe pas de définition consensuelle du sepsis néonatal, ce qui complique la pratique, la surveillance et la recherche. La revue fait le point sur les limites de l'hémoculture, les nouveaux outils diagnostiques, l'antibiothérapie et surtout la prévention.", "key_points_fr": ["Absence de définition universelle du sepsis néonatal : hétérogénéité des diagnostics et des traitements.", "Présentation clinique peu spécifique ; l'hémoculture a des performances limitées.", "Besoin d'outils diagnostiques pour éviter les antibiothérapies inutiles.", "La prévention (soins de base, hygiène, programmes qualité) reste le levier principal."], "pratique_fr": "Une bonne lecture de synthèse pour revoir l'épidémiologie, le diagnostic et l'antibiothérapie probabiliste du sepsis néonatal précoce et tardif.", "tags": ["Sepsis néonatal", "Néonatologie", "Hémoculture", "Revue"], "abstract_en": "Neonatal sepsis remains one of the key challenges of neonatal medicine, and together with preterm birth, causes almost 50% of all deaths globally for children younger than 5 years. Compared with advances achieved for other serious neonatal and early childhood conditions globally, progress in reducing neonatal sepsis has been much slower, especially in low-resource settings that have the highest burden of neonatal sepsis morbidity and mortality. By contrast to sepsis in older patients, there is no universally accepted neonatal sepsis definition. This poses substantial challenges in clinical practice, research, and health-care management, and has direct practical implications, such as diagnostic inconsistency, heterogeneous data collection and surveillance, and inappropriate treatment, health-resource allocation, and education. As the clinical manifestation of neonatal sepsis is frequently non-specific and the current diagnostic standard blood culture has performance limitations, new improved diagnostic techniques are required to guide appropriate and warranted antimicrobial treatment. Although antimicrobial therapy and supportive care continue as principal components of neonatal sepsis therapy, refining basic neonatal care to prevent sepsis through education and quality improvement initiatives remains paramount.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38944044/", "doi_url": "https://doi.org/10.1016/s0140-6736(24)00495-1", "pmc_url": "", "article_url": "https://doi.org/10.1016/s0140-6736(24)00495-1"}, {"id": "pmid-38543601", "pmid": "38543601", "pmcid": "PMC10974044", "doi": "10.3390/microorganisms12030550", "title": "The Kocher-Caird Criteria for Pediatric Septic Arthritis of the Hip: Time for a Change in the Kingella Era?", "title_fr": "Arthrite septique de hanche : faut-il revoir les critères de Kocher et Caird à l'ère de Kingella ?", "authors_list": ["Valisena S", "De Marco G", "Vazquez O", "Cochard B", "Steiger C", "Dayer R", "Ceroni D"], "authors_short": "Valisena S et al.", "journal": "Microorganisms", "journal_short": "Microorganisms", "year": 2024, "month_num": 3, "pub_date": "2024-03-10", "pub_date_fr": "mars 2024", "volume": "12", "issue": "3", "pages": "550", "pub_types": ["review-article", "Review", "Journal Article"], "category_id": "ioa", "category_label": "Infections ostéo-articulaires", "category_color": "#a16207", "audience": "Enfant", "study_fr": "Revue narrative · Microorganisms", "design": "Revue", "impact_factor": 4.2, "summary_fr": "Les critères de Kocher (fièvre > 38,5 °C, refus d'appui, VS > 40 mm/h, leucocytes > 12 000/mm³), complétés par la CRP > 20 mg/L de Caird, servent depuis vingt ans à distinguer l'arthrite septique de hanche de la synovite transitoire. Ils ont été établis avant la reconnaissance de Kingella kingae, responsable d'infections peu inflammatoires, ce qui expose à des faux négatifs.", "key_points_fr": ["Kocher : 4 critères, probabilité prédite de 99,6 % s'ils sont tous présents.", "Caird ajoute la CRP > 20 mg/L : 98 % de probabilité avec les 5 critères.", "Ces règles n'ont jamais été validées de façon robuste.", "Kingella kingae donne des tableaux pauci-symptomatiques mal captés par ces critères."], "pratique_fr": "Avant 4 ans, des critères de Kocher « rassurants » n'éliminent pas une arthrite à Kingella : PCR spécifique sur le liquide articulaire et réévaluation clinique.", "tags": ["Arthrite septique", "Hanche", "Kingella kingae", "Critères de Kocher", "Synovite transitoire"], "abstract_en": "Pediatric septic arthritis of the hip (SAH) in children is a severe pathology, requiring prompt diagnosis and treatment to avoid destructive sequelae of the joint. Its diagnosis can be challenging, however, due to its spectrum of manifestations and differential diagnosis. Last century, multiple research teams studied the curves of systemic inflammation markers to aid the differential diagnosis. Kocher showed that a history of fever >38.5 °C, non-weight bearing, an erythrocyte sedimentation rate >40 mm/h, and serum white blood cells >12,000/mm3 were highly suggestive of SAH, with a predicted probability of 99.6% when all these predictors manifested in pediatric patients. Caird validated these criteria, also adding a C-reactive protein >20 mg/L, reaching a 98% probability of SAH when these five criteria were present. The Kocher and the Caird criteria were then applied in multiple settings, but were never clearly validated. Moreover, they were studied and validated in the years when Kingella kingae was just emerging, and this was probably responsible for false-negative cases in multiple centers. For this reason, the Kocher and the Caird criteria are still at the center of a debate on the diagnostic tools for pediatric SAH. We provide a historical overview of the development of clinical and laboratory test algorithms for pediatric SAH. Further, new perspectives for future research on the prediction rules of pediatric SAH are here proposed.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38543601/", "doi_url": "https://doi.org/10.3390/microorganisms12030550", "pmc_url": "https://europepmc.org/article/PMC/PMC10974044", "article_url": "https://doi.org/10.3390/microorganisms12030550"}, {"id": "pmid-38245897", "pmid": "38245897", "pmcid": "PMC10900964", "doi": "10.1001/jama.2024.0196", "title": "Development and Validation of the Phoenix Criteria for Pediatric Sepsis and Septic Shock", "title_fr": "Critères de Phoenix : la nouvelle définition du sepsis et du choc septique de l'enfant", "authors_list": ["Sanchez-Pinto LN", "Bennett TD", "DeWitt PE", "Russell S", "Rebull MN", "Martin B", "Akech S", "Albers DJ", "Alpern ER", "Balamuth F", "Bembea M", "Chisti MJ", "Evans I", "Horvat CM", "Jaramillo-Bustamante JC", "Kissoon N", "Menon K", "Scott HF", "Weiss SL", "Wiens MO", "Zimmerman JJ", "Argent AC", "Sorce LR", "Schlapbach LJ", "Watson RS", "Society of Critical Care Medicine Pediatric Sepsis Definition Task Force", "Biban P", "Carrol E", "Chiotos K", "Flauzino De Oliveira C", "Hall MW", "Inwald D", "Ishimine P", "Levin M", "Lodha R", "Nadel S", "Nakagawa S", "Peters MJ", "Randolph AG", "Ranjit S", "Souza DC", "Tissieres P", "Wynn JL"], "authors_short": "Sanchez-Pinto LN et al.", "journal": "JAMA", "journal_short": "JAMA", "year": 2024, "month_num": 2, "pub_date": "2024-02-01", "pub_date_fr": "février 2024", "volume": "331", "issue": "8", "pages": "675-686", "pub_types": ["Research Support, Non-U.S. Gov't", "research-article", "Journal Article", "Research Support, N.I.H., Extramural"], "category_id": "sepsis", "category_label": "Sepsis & réanimation", "category_color": "#b91c1c", "audience": "Enfant", "study_fr": "Cohorte internationale rétrospective · 10 systèmes de santé · > 170 000 enfants", "design": "Cohorte internationale", "impact_factor": 55.0, "summary_fr": "La task force de la Society of Critical Care Medicine a dérivé et validé un nouveau score, le Phoenix Sepsis Score, à partir de quatre défaillances d'organe (respiratoire, cardiovasculaire, coagulation, neurologique). Le sepsis est défini par un score ≥ 2 chez un enfant suspect d'infection, et le choc septique par un sepsis avec au moins 1 point cardiovasculaire. Ces critères remplacent les critères IPSCC 2005 fondés sur le SIRS.", "key_points_fr": ["Fin du SIRS : le sepsis devient une infection avec dysfonction d'organe menaçant le pronostic vital.", "Sepsis = Phoenix ≥ 2 points ; choc septique = sepsis + ≥ 1 point cardiovasculaire.", "Meilleure valeur prédictive positive que les critères 2005, quel que soit le niveau de ressources.", "Validation dans des pays à hauts et faibles revenus (États-Unis, Colombie, Bangladesh, Chine, Kenya)."], "pratique_fr": "C'est désormais la définition de référence pour la recherche et le codage ; elle ne remplace pas le dépistage clinique précoce de l'enfant septique.", "tags": ["Sepsis", "Choc septique", "Phoenix", "Définition", "Réanimation pédiatrique"], "abstract_en": "Importance — The Society of Critical Care Medicine Pediatric Sepsis Definition Task Force sought to develop and validate new clinical criteria for pediatric sepsis and septic shock using measures of organ dysfunction through a data-driven approach.\n\nObjective — To derive and validate novel criteria for pediatric sepsis and septic shock across differently resourced settings.\n\nDesign, setting, and participants — Multicenter, international, retrospective cohort study in 10 health systems in the US, Colombia, Bangladesh, China, and Kenya, 3 of which were used as external validation sites. Data were collected from emergency and inpatient encounters for children (aged <18 years) from 2010 to 2019: 3 049 699 in the development (including derivation and internal validation) set and 581 317 in the external validation set.\n\nExposure — Stacked regression models to predict mortality in children with suspected infection were derived and validated using the best-performing organ dysfunction subscores from 8 existing scores. The final model was then translated into an integer-based score used to establish binary criteria for sepsis and septic shock.\n\nMain outcomes and measures — The primary outcome for all analyses was in-hospital mortality. Model- and integer-based score performance measures included the area under the precision recall curve (AUPRC; primary) and area under the receiver operating characteristic curve (AUROC; secondary). For binary criteria, primary performance measures were positive predictive value and sensitivity.\n\nResults — Among the 172 984 children with suspected infection in the first 24 hours (development set; 1.2% mortality), a 4-organ-system model performed best. The integer version of that model, the Phoenix Sepsis Score, had AUPRCs of 0.23 to 0.38 (95% CI range, 0.20-0.39) and AUROCs of 0.71 to 0.92 (95% CI range, 0.70-0.92) to predict mortality in the validation sets. Using a Phoenix Sepsis Score of 2 points or higher in children with suspected infection as criteria for sepsis and sepsis plus 1 or more cardiovascular point as criteria for septic shock resulted in a higher positive predictive value and higher or similar sensitivity compared with the 2005 International Pediatric Sepsis Consensus Conference (IPSCC) criteria across differently resourced settings.\n\nConclusions and relevance — The novel Phoenix sepsis criteria, which were derived and validated using data from higher- and lower-resource settings, had improved performance for the diagnosis of pediatric sepsis and septic shock compared with the existing IPSCC criteria.", "reading_min": 2, "pdf_file": "pdfs/PMID_38245897.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38245897/", "doi_url": "https://doi.org/10.1001/jama.2024.0196", "pmc_url": "https://europepmc.org/article/PMC/PMC10900964", "article_url": "https://doi.org/10.1001/jama.2024.0196"}, {"id": "pmid-38146260", "pmid": "38146260", "pmcid": "", "doi": "10.1542/peds.2023-062598", "title": "Short Oral Antibiotic Therapy for Pediatric Febrile Urinary Tract Infections: A Randomized Trial", "title_fr": "Pyélonéphrite de l'enfant : 5 jours d'amoxicilline-acide clavulanique suffisent", "authors_list": ["Montini G", "Tessitore A", "Console K", "Ronfani L", "Barbi E", "Pennesi M", "STOP Trial Group"], "authors_short": "Montini G et al.", "journal": "Pediatrics", "journal_short": "Pediatrics", "year": 2024, "month_num": 1, "pub_date": "2024-01-01", "pub_date_fr": "janvier 2024", "volume": "153", "issue": "1", "pages": "e2023062598", "pub_types": ["Equivalence Trial", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "antiinfectieux", "category_label": "Anti-infectieux & antibioprophylaxie", "category_color": "#047857", "audience": "Enfant", "study_fr": "Essai randomisé multicentrique de non-infériorité · 142 enfants de 3 mois à 5 ans", "design": "Essai randomisé", "impact_factor": 6.4, "summary_fr": "Chez l'enfant en bon état général avec une infection urinaire fébrile non compliquée, 5 jours d'amoxicilline-acide clavulanique per os (50 mg/kg/j) sont non inférieurs à 10 jours. Les récidives à 30 jours étaient même moins fréquentes dans le bras court (2,8 % vs 14,3 %).", "key_points_fr": ["Récidive d'IU à 30 jours : 2,8 % (5 jours) vs 14,3 % (10 jours).", "Récidive d'IU fébrile : 1,4 % vs 5,7 %.", "Concerne les IU fébriles non compliquées chez des enfants de 3 mois à 5 ans en bon état général.", "Petit effectif : à confirmer par des essais plus larges."], "pratique_fr": "Conforte la tendance aux durées courtes dans l'IU fébrile de l'enfant, à condition d'une bonne évolution clinique sous traitement.", "tags": ["Infection urinaire", "Pyélonéphrite", "Durée courte", "Amoxicilline-acide clavulanique"], "abstract_en": "Background and objectives — Febrile urinary tract infection (fUTI) in well-appearing children is conventionally treated with a standard 10-day course of oral antibiotic. The objective of this study is to determine the noninferiority (5% threshold) of a 5-day amoxicillin-clavulanate course compared with a 10-day regimen to treat fUTIs.\n\nMethods — This is a multicenter, investigator-initiated, parallel-group, randomized, controlled trial. We randomly assigned children aged 3 months to 5 years with a noncomplicated fUTI to receive amoxicillin-clavulanate 50 + 7.12 mg/kg/day orally in 3 divided doses for 5 or 10 days. The primary end point was the recurrence of a urinary tract infection within 30 days after the completion of therapy. Secondary end points were the difference in prevalence of clinical recovery, adverse drug-related events, and resistance to amoxicillin-clavulanic acid and/or to other antibiotics when a recurrent infection occurred.\n\nResults — From May 2020 through September 2022, 175 children were assessed for eligibility and 142 underwent randomization. The recurrence rate within 30 days of the end of therapy was 2.8% (2/72) in the short group and 14.3% (10/70) in the standard group. The difference between the 2 groups was -11.51% (95% confidence interval, -20.54 to -2.47). The recurrence rate of fUTI within 30 days from the end of therapy was 1.4% (1/72) in the short group and 5.7% (4/70) in the standard group (95% confidence interval, -10.4 to 1.75).\n\nConclusions — This study demonstrates that a 5-day course is noninferior to a 10-day course of oral amoxicillin-clavulanate.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38146260/", "doi_url": "https://doi.org/10.1542/peds.2023-062598", "pmc_url": "", "article_url": "https://doi.org/10.1542/peds.2023-062598"}, {"id": "pmid-38048787", "pmid": "38048787", "pmcid": "", "doi": "10.1016/s0140-6736(23)01968-2", "title": "Conservative versus liberal oxygenation targets in critically ill children (Oxy-PICU): a UK multicentre, open, parallel-group, randomised clinical trial", "title_fr": "Oxy-PICU : viser une SpO₂ de 88–92 % chez l'enfant ventilé en réanimation", "authors_list": ["Peters MJ", "Gould DW", "Ray S", "Thomas K", "Chang I", "Orzol M", "O'Neill L", "Agbeko R", "Au C", "Draper E", "Elliot-Major L", "Giallongo E", "Jones GAL", "Lampro L", "Lillie J", "Pappachan J", "Peters S", "Ramnarayan P", "Sadique Z", "Rowan KM", "Harrison DA", "Mouncey PR", "Oxy-PICU Investigators of the Paediatric Critical Care Society Study Group (PCCS-SG)"], "authors_short": "Peters MJ et al.", "journal": "The Lancet", "journal_short": "Lancet", "year": 2023, "month_num": 12, "pub_date": "2023-12-01", "pub_date_fr": "décembre 2023", "volume": "403", "issue": "10424", "pages": "355-364", "pub_types": ["Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Pragmatic Clinical Trial", "Journal Article"], "category_id": "pediatrie", "category_label": "Pédiatrie générale", "category_color": "#c2410c", "audience": "Enfant", "study_fr": "Essai randomisé pragmatique · 15 réanimations pédiatriques britanniques · 2 040 enfants", "design": "Essai randomisé", "impact_factor": 88.5, "summary_fr": "Chez l'enfant admis en urgence en réanimation et ventilé invasivement, une cible d'oxygénation conservatrice (SpO₂ 88–92 %) a été comparée à une cible libérale (SpO₂ > 94 %). La stratégie conservatrice a légèrement mais significativement réduit la durée des suppléances d'organe ou le décès à 30 jours, sans excès d'événements indésirables.", "key_points_fr": ["Critère principal : durée de suppléance d'organe à J30, le décès étant le pire score.", "Index probabiliste 0,53 en faveur de la cible conservatrice (OR ajusté 0,84 ; p = 0,04).", "Événements indésirables prédéfinis : 3 % (conservateur) vs 4 % (libéral).", "Les auteurs suggèrent aussi un bénéfice économique d'une adoption large."], "pratique_fr": "En réanimation pédiatrique, l'hyperoxie « par sécurité » n'apporte rien : une cible de SpO₂ à 88–92 % est raisonnable chez l'enfant ventilé.", "tags": ["Réanimation pédiatrique", "Oxygénothérapie", "Ventilation", "Essai pragmatique"], "abstract_en": "Background — The optimal target for systemic oxygenation in critically ill children is unknown. Liberal oxygenation is widely practiced, but has been associated with harm in paediatric patients. We aimed to evaluate whether conservative oxygenation would reduce duration of organ support or incidence of death compared to standard care.\n\nMethods — Oxy-PICU was a pragmatic, multicentre, open-label, randomised controlled trial in 15 UK paediatric intensive care units (PICUs). Children admitted as an emergency, who were older than 38 weeks corrected gestational age and younger than 16 years receiving invasive ventilation and supplemental oxygen were randomly allocated in a 1:1 ratio via a concealed, central, web-based randomisation system to conservative peripheral oxygen saturations ([SpO2] 88-92%) or liberal (SpO2 >94%) targets. The primary outcome was the duration of organ support at 30 days following random allocation, a rank-based endpoint with death either on or before day 30 as the worst outcome (a score equating to 31 days of organ support), with survivors assigned a score between 1 and 30 depending on the number of calendar days of organ support received. The primary effect estimate was the probabilistic index, a value greater than 0·5 indicating more than 50% probability that conservative oxygenation is superior to liberal oxygenation for a randomly selected patient. All participants in whom consent was available were included in the intention-to-treat analysis. The completed study was registered with the ISRCTN registry (ISRCTN92103439).\n\nFindings — Between Sept 1, 2020, and May 15, 2022, 2040 children were randomly allocated to conservative or liberal oxygenation groups. Consent was available for 1872 (92%) of 2040 children. The conservative oxygenation group comprised 939 children (528 [57%] of 927 were female and 399 [43%] of 927 were male) and the liberal oxygenation group included 933 children (511 [56%] of 920 were female and 409 [45%] of 920 were male). Duration of organ support or death in the first 30 days was significantly lower in the conservative oxygenation group (probabilistic index 0·53, 95% CI 0·50-0·55; p=0·04 Wilcoxon rank-sum test, adjusted odds ratio 0·84 [95% CI 0·72-0·99]). Prespecified adverse events were reported in 24 (3%) of 939 patients in the conservative oxygenation group and 36 (4%) of 933 patients in the liberal oxygenation group.\n\nInterpretation — Among invasively ventilated children who were admitted as an emergency to a PICU receiving supplemental oxygen, a conservative oxygenation target resulted in a small, but significant, greater probability of a better outcome in terms of duration of organ support at 30 days or death when compared with a liberal oxygenation target. Widespread adoption of a conservative oxygenation saturation target (SpO2 88-92%) could help improve outcomes and reduce costs for the sickest children admitted to PICUs.\n\nFunding — UK National Institute for Health and Care Research Health Technology Assessment Programme.", "reading_min": 2, "pdf_file": "pdfs/PMID_38048787.pdf", "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/38048787/", "doi_url": "https://doi.org/10.1016/s0140-6736(23)01968-2", "pmc_url": "", "article_url": "https://doi.org/10.1016/s0140-6736(23)01968-2"}, {"id": "pmid-37880823", "pmid": "37880823", "pmcid": "", "doi": "10.1093/jpids/piad095", "title": "Assessing Risk for Complications in Acute Hematogenous Osteomyelitis in Children: Validation of 2 Predictive Scores", "title_fr": "Ostéomyélite aiguë de l'enfant : deux scores pour prédire les complications", "authors_list": ["Sarmiento Clemente A", "McNeil JC", "Hultén KG", "Vallejo JG", "Scheurer ME", "Kaplan SL"], "authors_short": "Sarmiento Clemente A et al.", "journal": "Journal of the Pediatric Infectious Diseases Society", "journal_short": "J Pediatric Infect Dis Soc", "year": 2023, "month_num": 12, "pub_date": "2023-12-01", "pub_date_fr": "décembre 2023", "volume": "12", "issue": "12", "pages": "610-617", "pub_types": ["Journal Article"], "category_id": "ioa", "category_label": "Infections ostéo-articulaires", "category_color": "#a16207", "audience": "Enfant", "study_fr": "Étude rétrospective de validation externe · 418 enfants", "design": "Cohorte rétrospective", "impact_factor": 2.6, "summary_fr": "Les scores A-SCORE (complications aiguës) et C-SCORE (complications chroniques) ont été validés sur une cohorte externe d'ostéomyélites aiguës hématogènes. L'A-SCORE prédit bien une évolution aiguë compliquée (aire sous la courbe 0,87, VPN 92 %). Le C-SCORE est moins spécifique que prévu mais garde une bonne VPN (94 %) pour les séquelles chroniques.", "key_points_fr": ["Évolution aiguë compliquée chez 25 % des enfants ; complication chronique chez 13,5 %.", "A-SCORE : abcès osseux, fièvre > 48 h sous antibiotiques, arthrite associée, forme disséminée, contrôle de la source tardif.", "C-SCORE : forme disséminée, débridement osseux, CRP ≥ 100 mg/L à J2–J4.", "L'atteinte tibiale et une bactériémie ≥ 2 jours sont aussi associées aux complications."], "pratique_fr": "Des outils simples pour décider du niveau de surveillance et de la durée du suivi orthopédique après une ostéomyélite.", "tags": ["Ostéomyélite", "Score prédictif", "Complications", "Suivi"], "abstract_en": "Background — Acute hematogenous osteomyelitis (AHO) can be associated with severe complications which can be difficult to predict in the clinical setting. The previously published predictive acute complication score (\"A-SCORE\") and chronic complication score (\"C-SCORE\") show promise, however, further external validation is needed.\n\nMethods — We performed a retrospective study of 418 children with AHO and analyzed the performance of A-SCORE (variables included bone abscess, fever after 48 h of starting antibiotics, suppurative arthritis, disseminated disease, and delayed source control) to predict risk for acute complicated course (treatment failure, prolonged admission, and/or need for ≥2 bone debridements) and C-SCORE (includes disseminated disease, bone debridement, and CRP ≥10 mg/dL at 2-4 days after starting antibiotics) to predict chronic complications (growth restriction, pathologic fracture, chronic osteomyelitis, avascular necrosis, joint deformity, and/or frozen joint).\n\nResults — An acute complicated course occurred in 106/418 (25.4%); 51/380 (13.5%) with complete follow-up data had a chronic complication. The A-SCORE performed with similar specificity (78%) and negative predictive value (NPV) (92%), and higher sensitivity (81%) and increased area under the receiver operating curve (AUC) (0.87) in our population. The C-SCORE performed with similar sensitivity (64%) and NPV (94%) but had lower specificity (86%) and AUC (0.71) than originally reported. Other variables associated with development of complications such as tibia involvement and bacteremia ≥2 days were identified but did not result in significantly improved predictive scores.\n\nConclusions — Predictive A-SCORE and C-SCORE for AHO complications in children may help guide acute management and long-term follow-up decisions. Prospective studies are needed to determine their applicability.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37880823/", "doi_url": "https://doi.org/10.1093/jpids/piad095", "pmc_url": "", "article_url": "https://doi.org/10.1093/jpids/piad095"}, {"id": "pmid-37952582", "pmid": "37952582", "pmcid": "", "doi": "10.1016/j.idnow.2023.104832", "title": "Clinical practice recommendations for infectious disease management of diabetic foot infection (DFI) - 2023 SPILF", "title_fr": "Infections du pied diabétique : les recommandations SPILF 2023", "authors_list": ["Bonnet E", "Maulin L", "Senneville E", "Castan B", "Fourcade C", "Loubet P", "Poitrenaud D", "Schuldiner S", "Sotto A", "Lavigne JP", "Lesprit P", "individual members of the “Review group”"], "authors_short": "Bonnet E et al.", "journal": "Infectious Diseases Now", "journal_short": "Infect Dis Now", "year": 2023, "month_num": 11, "pub_date": "2023-11-10", "pub_date_fr": "novembre 2023", "volume": "54", "issue": "1", "pages": "104832", "pub_types": ["Practice Guideline", "Journal Article"], "category_id": "ioa", "category_label": "Infections ostéo-articulaires", "category_color": "#a16207", "audience": "Adulte", "study_fr": "Recommandations de pratique clinique · SPILF", "design": "Recommandations", "impact_factor": 2.2, "summary_fr": "La SPILF actualise ses recommandations de 2006, en complément de celles de l'IWGDF, en se concentrant sur le diagnostic microbiologique et l'antibiothérapie. La gravité doit être classée selon l'IWGDF, les prélèvements ne se font qu'en cas de signes cliniques d'infection, et l'antibiothérapie probabiliste doit toujours couvrir le S. aureus sensible à la méticilline. En cas d'ostéite, radiographie standard et biopsie osseuse.", "key_points_fr": ["Classer la gravité selon l'IWGDF est obligatoire.", "Prélèvements uniquement en présence de signes cliniques d'infection, selon un protocole strict.", "Probabiliste adaptée au grade et à l'ancienneté de la plaie, couvrant toujours le SAMS.", "Ostéite : radio standard en première intention, biopsie osseuse microbiologique ; histologie non recommandée."], "pratique_fr": "Réévaluation précoce, durées souvent raccourcies et fortes doses en cas d'ostéite documentée : les messages clés de la SPILF.", "tags": ["Pied diabétique", "Ostéite", "SPILF", "Recommandations françaises"], "abstract_en": "In march 2020, the International Working Group on the Diabetic Foot (IWGDF) published an update of the 2015 guidelines on the diagnosis and management of diabetic foot infection (DFI). While we (the French ID society, SPILF) endorsed some of these recommendations, we wanted to update our own 2006 guidelines and specifically provide informative elements on modalities of microbiological diagnosis and antibiotic treatment (especially first- and second-line regiments, oral switch and duration). The recommendations put forward in the present guidelines are addressed to healthcare professionals managing patients with DFI and more specifically focused on infectious disease management of this type of infection, which clearly needs a multidisciplinary approach. Staging of the severity of the infection is mandatory using the classification drawn up by the IWGDF. Microbiological samples should be taken only in the event of clinical signs suggesting infection in accordance with a strict preliminarily established protocol. Empirical antibiotic therapy should be chosen according to the IWGDF grade of infection and duration of the wound, but must always cover methicillin-sensitive Staphylococcus aureus. Early reevaluation of the patient is a fundamental step, and duration of antibiotic therapy can be shortened in many situations. When osteomyelitis is suspected, standard foot radiograph is the first-line imagery examination and a bone biopsy should be performed for microbiological documentation. Histological analysis of the bone sample is no longer recommended. High dosages of antibiotics are recommended in cases of confirmed osteomyelitis.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37952582/", "doi_url": "https://doi.org/10.1016/j.idnow.2023.104832", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.idnow.2023.104832"}, {"id": "pmid-37851875", "pmid": "37851875", "pmcid": "", "doi": "10.1056/nejmoa2301401", "title": "Trial of Vancomycin and Cefazolin as Surgical Prophylaxis in Arthroplasty", "title_fr": "Antibioprophylaxie en chirurgie prothétique : ajouter la vancomycine à la céfazoline n'apporte rien", "authors_list": ["Peel TN", "Astbury S", "Cheng AC", "Paterson DL", "Buising KL", "Spelman T", "Tran-Duy A", "Adie S", "Boyce G", "McDougall C", "Molnar R", "Mulford J", "Rehfisch P", "Solomon M", "Crawford R", "Harris-Brown T", "Roney J", "Wisniewski J", "de Steiger R", "ASAP Trial Group"], "authors_short": "Peel TN et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2023, "month_num": 10, "pub_date": "2023-10-01", "pub_date_fr": "octobre 2023", "volume": "389", "issue": "16", "pages": "1488-1498", "pub_types": ["Equivalence Trial", "Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "antiinfectieux", "category_label": "Anti-infectieux & antibioprophylaxie", "category_color": "#047857", "audience": "Adulte", "study_fr": "Essai randomisé en double aveugle contre placebo · 4 239 patients", "design": "Essai randomisé", "impact_factor": 78.5, "summary_fr": "Chez des adultes non colonisés à SARM opérés d'une arthroplastie, l'ajout de 1,5 g de vancomycine à la céfazoline n'a pas réduit les infections du site opératoire à 90 jours (4,5 % vs 3,5 %). Chez les prothèses de genou, elles étaient même plus fréquentes avec la vancomycine, et les réactions d'hypersensibilité deux fois plus nombreuses.", "key_points_fr": ["Infection du site opératoire : 4,5 % (vancomycine) vs 3,5 % (placebo), RR 1,28, non significatif.", "Genou : 5,7 % vs 3,7 % (RR 1,52) ; hanche : pas de différence.", "Hypersensibilité : 1,2 % vs 0,5 % ; insuffisance rénale aiguë moins fréquente sous vancomycine.", "Population sans colonisation connue à SARM."], "pratique_fr": "Céfazoline seule chez le patient non porteur de SARM : pas de double antibioprophylaxie systématique en chirurgie prothétique.", "tags": ["Antibioprophylaxie", "Prothèse articulaire", "Vancomycine", "Céfazoline", "Infection du site opératoire"], "abstract_en": "Background — The addition of vancomycin to beta-lactam prophylaxis in arthroplasty may reduce surgical-site infections; however, the efficacy and safety are unclear.\n\nMethods — In this multicenter, double-blind, superiority, placebo-controlled trial, we randomly assigned adult patients without known methicillin-resistant Staphylococcus aureus (MRSA) colonization who were undergoing arthroplasty to receive 1.5 g of vancomycin or normal saline placebo, in addition to cefazolin prophylaxis. The primary outcome was surgical-site infection within 90 days after surgery.\n\nResults — A total of 4239 patients underwent randomization. Among 4113 patients in the modified intention-to-treat population (2233 undergoing knee arthroplasty, 1850 undergoing hip arthroplasty, and 30 undergoing shoulder arthroplasty), surgical-site infections occurred in 91 of 2044 patients (4.5%) in the vancomycin group and in 72 of 2069 patients (3.5%) in the placebo group (relative risk, 1.28; 95% confidence interval [CI], 0.94 to 1.73; P = 0.11). Among patients undergoing knee arthroplasty, surgical-site infections occurred in 63 of 1109 patients (5.7%) in the vancomyin group and in 42 of 1124 patients (3.7%) in the placebo group (relative risk, 1.52; 95% CI, 1.04 to 2.23). Among patients undergoing hip arthroplasty, surgical-site infections occurred in 28 of 920 patients (3.0%) in the vancomyin group and in 29 of 930 patients (3.1%) in the placebo group (relative risk, 0.98; 95% CI, 0.59 to 1.63). Adverse events occurred in 35 of 2010 patients (1.7%) in the vancomycin group and in 35 of 2030 patients (1.7%) in the placebo group, including hypersensitivity reactions in 24 of 2010 patients (1.2%) and 11 of 2030 patients (0.5%), respectively (relative risk, 2.20; 95% CI, 1.08 to 4.49), and acute kidney injury in 42 of 2010 patients (2.1%) and 74 of 2030 patients (3.6%), respectively (relative risk, 0.57; 95% CI, 0.39 to 0.83).\n\nConclusions — The addition of vancomycin to cefazolin prophylaxis was not superior to placebo for the prevention of surgical-site infections in arthroplasty among patients without known MRSA colonization. (Funded by the Australian National Health and Medical Research Council; Australian New Zealand Clinical Trials Registry number, ACTRN12618000642280.).", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37851875/", "doi_url": "https://doi.org/10.1056/nejmoa2301401", "pmc_url": "", "article_url": "https://doi.org/10.1056/nejmoa2301401"}, {"id": "pmid-37741341", "pmid": "37741341", "pmcid": "", "doi": "10.1016/j.idnow.2023.104789", "title": "Antibiotic therapy for osteoarticular infections in 2023: Proposals from the Pediatric Infectious Pathology Group (GPIP)", "title_fr": "Infections ostéo-articulaires de l'enfant : les propositions 2023 du GPIP", "authors_list": ["Lorrot M", "Gillet Y", "Basmaci R", "Bréhin C", "Dommergues MA", "Favier M", "Jeziorski E", "Panetta L", "Pinquier D", "Ouziel A", "Grimprel E", "Cohen R"], "authors_short": "Lorrot M et al.", "journal": "Infectious Diseases Now", "journal_short": "Infect Dis Now", "year": 2023, "month_num": 9, "pub_date": "2023-09-21", "pub_date_fr": "septembre 2023", "volume": "53", "issue": "8S", "pages": "104789", "pub_types": ["Review", "Journal Article"], "category_id": "ioa", "category_label": "Infections ostéo-articulaires", "category_color": "#a16207", "audience": "Enfant", "study_fr": "Recommandations du Groupe de pathologie infectieuse pédiatrique (GPIP)", "design": "Recommandations", "impact_factor": 2.2, "summary_fr": "Le GPIP actualise la prise en charge des IOA de l'enfant, le plus souvent hématogènes et survenant avant 5 ans. Staphylococcus aureus est en cause à tout âge et Kingella kingae est très fréquent entre 6 mois et 4 ans. L'antibiothérapie probabiliste repose sur la céfazoline IV à forte dose, avec un relais oral précoce après environ 3 jours dans les formes non compliquées.", "key_points_fr": ["Probabiliste : céfazoline IV 150 mg/kg/j ; drainage chirurgical si arthrite ou abcès sous-périosté.", "Relais oral dès J3 si évolution favorable : amoxicilline-acide clavulanique (80 mg/kg/j) ou céfalexine (150 mg/kg/j).", "Durées minimales : 14 jours pour une arthrite, 3 semaines pour une ostéomyélite.", "4 à 6 semaines pour le bassin, les spondylodiscites, les formes sévères, le nouveau-né et l'immunodéprimé."], "pratique_fr": "Le texte de référence français pour les IOA pédiatriques : schémas courts, relais oral précoce et doses élevées de bêtalactamines.", "tags": ["Ostéomyélite", "Arthrite septique", "Kingella kingae", "GPIP", "Céfazoline", "Recommandations françaises"], "abstract_en": "Most osteoarticular infections (OAI) occur via the hematogenous route, affect children under 5 years of age old, and include osteomyelitis, septic arthritis, osteoarthritis and spondylodiscitis. Early diagnosis and prompt treatment are needed to avoid complications. Children with suspected OAI should be hospitalized at the start of therapy. Surgical drainage is indicated in patients with septic arthritis or periosteal abscess. Staphylococcus aureus is implicated in OAI in children at all ages; Kingella kingae is a very common causative pathogen in children from 6 months to 4 years old. The French Pediatric Infectious Disease Group recommends empirical antibiotic therapy with appropriate coverage against methicillin-sensitive S. aureus (MSSA) with high doses (150 mg/kg/d) of intravenous cefazolin. In most children presenting uncomplicated OAI with favorable outcome (disappearance of fever and pain), short intravenous antibiotic therapy during 3 days can be followed by oral therapy. In the absence of bacteriological identification, oral relay is carried out with the amoxicillin/clavulanate combination (80 mg/kg/d of amoxicillin) or cefalexin (150 mg/kg/d). If the bacterial species is identified, antibiotic therapy will be adapted to antibiotic susceptibility. The minimum total duration of antibiotic therapy should be 14 days for septic arthritis, 3 weeks for osteomyelitis and 4-6 weeks for OAI of the pelvis, spondylodiscitis and more severe OAI, and those evolving slowly under treatment or with an underlying medical condition (neonate, infant under 3 months of old, immunocompromised patients). Treatment of spondylodiscitis and severe OAI requires systematic orthopedic advice.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37741341/", "doi_url": "https://doi.org/10.1016/j.idnow.2023.104789", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.idnow.2023.104789"}, {"id": "pmid-37741342", "pmid": "37741342", "pmcid": "", "doi": "10.1016/j.idnow.2023.104788", "title": "Antibiotic treatment of neuro-meningeal infections", "title_fr": "Méningites et abcès cérébraux de l'enfant : la mise à jour 2023 du GPIP", "authors_list": ["Gillet Y", "Grimprel E", "Haas H", "Yaghy M", "Dubos F", "Cohen R"], "authors_short": "Gillet Y et al.", "journal": "Infectious Diseases Now", "journal_short": "Infect Dis Now", "year": 2023, "month_num": 9, "pub_date": "2023-09-21", "pub_date_fr": "septembre 2023", "volume": "53", "issue": "8S", "pages": "104788", "pub_types": ["Review", "Journal Article"], "category_id": "orl_resp", "category_label": "Respiratoire, ORL, peau & méninges", "category_color": "#1d4ed8", "audience": "Enfant", "study_fr": "Recommandations du GPIP · Infectious Diseases Now", "design": "Recommandations", "impact_factor": 2.2, "summary_fr": "Grâce au vaccin pneumococcique conjugué et à l'observatoire national des méningites, aucune méningite à pneumocoque résistant aux C3G n'a été observée récemment en France. Le GPIP limite donc la vancomycine à la phase secondaire, si la CMI de la C3G est > 0,5 mg/L, et abandonne l'association ciprofloxacine-céfotaxime pour les méningites à E. coli du nouveau-né. Les abcès cérébraux communautaires associent céfotaxime et métronidazole.", "key_points_fr": ["Pneumocoque : pas de vancomycine d'emblée ; seulement si CMI C3G > 0,5 mg/L.", "Fin de l'association ciprofloxacine + céfotaxime pour E. coli chez le nouveau-né et le jeune nourrisson.", "Abcès cérébral : imagerie de qualité, prélèvements avant antibiotiques si possible, céfotaxime + métronidazole.", "L'observatoire national des méningites de l'enfant guide les adaptations futures."], "pratique_fr": "À connaître pour toute méningite bactérienne de l'enfant : simplification de l'antibiothérapie probabiliste en France.", "tags": ["Méningite", "Pneumocoque", "Abcès cérébral", "GPIP", "Recommandations françaises"], "abstract_en": "In France, conjugated pneumococcal vaccination has considerably modified the profile of pneumococcal meningitis by eliminating the most virulent strains resistant to beta-lactams. Over recent years, the nationwide pediatric meningitis network of the Pediatric Infectious Disease Group (GPIP) and the National Reference Centre of Pneumococci have not recorded any cases of meningitis due to pneumococcus resistant to third-generation cephalosporins (C3G), even though in 2021, strains with a less favorable profile appeared to emerge. These recent data justify renewal of the 2016 recommendations and limitation of vancomycin to the secondary phase of treatment of pneumococcal meningitis when the MIC of the isolated strain against injectable C3Gs is >0.5 mg/L. The only major change proposed by the GPIP in this 2023 update of its recommendations is discontinuation of the recommendation of a combination of ciprofloxacin and cefotaxime in Escherichia coli meningitis in newborns and young infants. The nationwide observatory of meningitis in children is a valuable tool because of its completeness and its continuity over the past 15 years. The maintenance of epidemiological surveillance will allow us to adapt new therapeutic regimens to the evolution of pneumococcal susceptibility profiles and to future serotype-specific changes. Community-acquired cerebral abscesses are rare diseases, of which the management requires a rigorous approach: high-quality imaging, bacteriological sampling prior to antibiotic therapy whenever possible, and antibiotic treatment including metronidazole in addition to cefotaxime. Multidisciplinary collaboration, including infectious disease and neurosurgical advice, is always called for.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37741342/", "doi_url": "https://doi.org/10.1016/j.idnow.2023.104788", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.idnow.2023.104788"}, {"id": "pmid-37730165", "pmid": "37730165", "pmcid": "", "doi": "10.1016/j.idnow.2023.104785", "title": "Antimicrobial treatment of ENT infections", "title_fr": "Infections ORL de l'enfant : quand traiter, quand s'abstenir (GPIP 2023)", "authors_list": ["Cohen R", "Madhi F", "Thollot F", "Hau I", "Vie le Sage F", "Lemaître C", "Magendie C", "Werner A", "Gelbert N", "Cohen JF", "Couloigner V"], "authors_short": "Cohen R et al.", "journal": "Infectious Diseases Now", "journal_short": "Infect Dis Now", "year": 2023, "month_num": 9, "pub_date": "2023-09-18", "pub_date_fr": "septembre 2023", "volume": "53", "issue": "8S", "pages": "104785", "pub_types": ["Review", "Journal Article"], "category_id": "orl_resp", "category_label": "Respiratoire, ORL, peau & méninges", "category_color": "#1d4ed8", "audience": "Enfant", "study_fr": "Recommandations du GPIP · Infectious Diseases Now", "design": "Recommandations", "impact_factor": 2.2, "summary_fr": "Les infections ORL sont les infections les plus fréquentes de l'enfant et la première cause de prescription d'antibiotiques, alors qu'elles sont majoritairement virales. Le GPIP rappelle les situations sans antibiotique, la place du TDR streptococcique dans l'angine et les indications restreintes dans l'otite moyenne aiguë. L'amoxicilline reste le traitement de première ligne.", "key_points_fr": ["Pas d'antibiotique : rhinopharyngite, la plupart des angines, laryngite, otite congestive, otite séromuqueuse.", "Angine : antibiotique seulement si TDR streptococcique positif.", "OMA purulente : traiter avant 2 ans, et au-delà seulement si forme symptomatique ou compliquée.", "Mastoïdite, épiglottite, abcès rétro/parapharyngés, ethmoïdite : urgences, hospitalisation et IV."], "pratique_fr": "Une fiche synthétique idéale pour les consultations aux urgences et pour former les internes au bon usage des antibiotiques en ORL.", "tags": ["ORL", "Otite moyenne aiguë", "Angine", "GPIP", "Recommandations françaises"], "abstract_en": "Ear, nose and throat (ENT) or upper respiratory tract infections (URTI) are the most common infections in children and the leading causes of antibiotic prescriptions. In most cases, these infections are due to (or are triggered by) viruses and even when bacterial species are implicated, recovery is usually spontaneous. The first imperative is to refrain from prescribing antibiotics in a large number of URTIs: common cold, most cases of sore throat, laryngitis, congestive otitis, and otitis media with effusion. On the contrary, a decision to treat sore throats with antibiotics is based primarily on the positivity of the Group A Streptococcus (GAS) rapid antigen diagnostic tests. For ear infections, only (a) purulent acute otitis media in children under 2 years of age and (b) complicated or symptomatic forms of purulent acute otitis media (PAOM) in older children should be treated with antibiotics. Amoxicillin is the first-line treatment in the most cases of ambulatory ENT justifying antibiotics. Severe ENT infections (mastoiditis, epiglottitis, retro- and parapharyngeal abscesses, ethmoiditis) are therapeutic emergencies necessitating hospitalization and initial intravenous antibiotic therapy.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37730165/", "doi_url": "https://doi.org/10.1016/j.idnow.2023.104785", "pmc_url": "", "article_url": "https://doi.org/10.1016/j.idnow.2023.104785"}, {"id": "pmid-37702442", "pmid": "37702442", "pmcid": "", "doi": "10.1056/nejmoa2300161", "title": "Antibiotic Prophylaxis in Infants with Grade III, IV, or V Vesicoureteral Reflux", "title_fr": "Reflux vésico-urétéral de haut grade : l'antibioprophylaxie réduit un peu les infections urinaires", "authors_list": ["Morello W", "Baskin E", "Jankauskiene A", "Yalcinkaya F", "Zurowska A", "Puccio G", "Serafinelli J", "La Manna A", "Krzemień G", "Pennesi M", "La Scola C", "Becherucci F", "Brugnara M", "Yuksel S", "Mekahli D", "Chimenz R", "De Palma D", "Zucchetta P", "Vajauskas D", "Drozdz D", "Szczepanska M", "Caliskan S", "Lombet J", "Minoli DG", "Guarino S", "Gulleroglu K", "Ruzgiene D", "Szmigielska A", "Barbi E", "Ozcakar ZB", "Kranz A", "Pasini A", "Materassi M", "De Rechter S", "Ariceta G", "Weber LT", "Marzuillo P", "Alberici I", "Taranta-Janusz K", "Caldas Afonso A", "Tkaczyk M", "Català M", "Cabrera Sevilla JE", "Mehls O", "Schaefer F", "Montini G", "PREDICT Study Group"], "authors_short": "Morello W et al.", "journal": "The New England Journal of Medicine", "journal_short": "N Engl J Med", "year": 2023, "month_num": 9, "pub_date": "2023-09-12", "pub_date_fr": "septembre 2023", "volume": "389", "issue": "11", "pages": "987-997", "pub_types": ["Research Support, Non-U.S. Gov't", "Multicenter Study", "Randomized Controlled Trial", "Journal Article"], "category_id": "antiinfectieux", "category_label": "Anti-infectieux & antibioprophylaxie", "category_color": "#047857", "audience": "Enfant", "study_fr": "Essai randomisé PREDICT · 39 centres européens · 292 nourrissons", "design": "Essai randomisé", "impact_factor": 78.5, "summary_fr": "Chez des nourrissons de 1 à 5 mois avec un reflux de grade III à V, sans infection urinaire antérieure, l'antibioprophylaxie continue pendant 2 ans réduit le risque de première infection urinaire (21 % vs 36 %). Il faut traiter 7 enfants pour éviter une infection, sans effet sur les cicatrices rénales ni sur le débit de filtration glomérulaire, et au prix de germes plus résistants.", "key_points_fr": ["Première IU : 21,2 % sous prophylaxie vs 35,6 % sans traitement (HR 0,55).", "Nombre de sujets à traiter : 7 enfants pendant 2 ans.", "64 % des enfants non traités n'ont fait aucune infection urinaire.", "Plus de Pseudomonas, de germes non-E. coli et de résistances sous prophylaxie."], "pratique_fr": "Le bénéfice existe mais il est modeste : la prophylaxie se discute au cas par cas, en pesant le risque de sélection de résistances.", "tags": ["Antibioprophylaxie", "Reflux vésico-urétéral", "Infection urinaire", "Néphrologie pédiatrique"], "abstract_en": "Background — The efficacy of continuous antibiotic prophylaxis in preventing urinary tract infection (UTI) in infants with grade III, IV, or V vesicoureteral reflux is controversial.\n\nMethods — In this investigator-initiated, randomized, open-label trial performed in 39 European centers, we randomly assigned infants 1 to 5 months of age with grade III, IV, or V vesicoureteral reflux and no previous UTIs to receive continuous antibiotic prophylaxis (prophylaxis group) or no treatment (untreated group) for 24 months. The primary outcome was the occurrence of the first UTI during the trial period. Secondary outcomes included new kidney scarring and the estimated glomerular filtration rate (GFR) at 24 months.\n\nResults — A total of 292 participants underwent randomization (146 per group). Approximately 75% of the participants were male; the median age was 3 months, and 235 participants (80.5%) had grade IV or V vesicoureteral reflux. In the intention-to-treat analysis, a first UTI occurred in 31 participants (21.2%) in the prophylaxis group and in 52 participants (35.6%) in the untreated group (hazard ratio, 0.55; 95% confidence interval [CI], 0.35 to 0.86; P = 0.008); the number needed to treat for 2 years to prevent one UTI was 7 children (95% CI, 4 to 29). Among untreated participants, 64.4% had no UTI during the trial. The incidence of new kidney scars and the estimated GFR at 24 months did not differ substantially between the two groups. Pseudomonas species, other non-Escherichia coli organisms, and antibiotic resistance were more common in UTI isolates obtained from participants in the prophylaxis group than in isolates obtained from those in the untreated group. Serious adverse events were similar in the two groups.\n\nConclusions — In infants with grade III, IV, or V vesicoureteral reflux and no previous UTIs, continuous antibiotic prophylaxis provided a small but significant benefit in preventing a first UTI despite an increased occurrence of non-E. coli organisms and antibiotic resistance. (Funded by the Italian Ministry of Health and others; PREDICT ClinicalTrials.gov number, NCT02021006; EudraCT number, 2013-000309-21.).", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37702442/", "doi_url": "https://doi.org/10.1056/nejmoa2300161", "pmc_url": "", "article_url": "https://doi.org/10.1056/nejmoa2300161"}, {"id": "pmid-37180594", "pmid": "37180594", "pmcid": "PMC10167988", "doi": "10.1093/ofid/ofad188", "title": "Unexpected Increase in Invasive Group A Streptococcal Infections in Children After Respiratory Viruses Outbreak in France: A 15-Year Time-Series Analysis", "title_fr": "Infections invasives à streptocoque A chez l'enfant en France : la flambée de l'hiver 2022", "authors_list": ["Lassoued Y", "Assad Z", "Ouldali N", "Caseris M", "Mariani P", "Birgy A", "Bonacorsi S", "Bidet P", "Faye A"], "authors_short": "Lassoued Y et al.", "journal": "Open Forum Infectious Diseases", "journal_short": "Open Forum Infect Dis", "year": 2023, "month_num": 4, "pub_date": "2023-04-06", "pub_date_fr": "avril 2023", "volume": "10", "issue": "5", "pages": "ofad188", "pub_types": ["brief-report", "Journal Article"], "category_id": "vaccins", "category_label": "Vaccins & infections communautaires", "category_color": "#0f766e", "audience": "Enfant", "study_fr": "Série temporelle sur 15 ans · réseau pédiatrique français", "design": "Série temporelle", "impact_factor": 3.8, "summary_fr": "Une analyse de 15 ans de données pédiatriques françaises montre une hausse inattendue des infections invasives à streptocoque du groupe A à partir d'octobre 2022, dominée par les pleurésies purulentes. Cette hausse est survenue en même temps qu'une circulation intense des virus respiratoires, après la levée des mesures barrières.", "key_points_fr": ["Hausse marquée des infections invasives à SGA depuis octobre 2022.", "Les empyèmes pleuraux représentent la majorité de cette augmentation.", "Survenue concomitante à l'épidémie de virus respiratoires (grippe, VRS).", "Message d'alerte pour les cliniciens dans les périodes de forte circulation virale."], "pratique_fr": "Devant une pneumonie qui s'aggrave après une virose, chercher activement un empyème et penser au streptocoque A, surtout en période épidémique.", "tags": ["Streptocoque A", "iGAS", "Empyème", "Dette immunitaire", "France"], "abstract_en": "In a 15-year pediatric time-series analysis, we showed a rise of invasive Group A streptococcal (iGAS) infections since October 2022, mainly involving pleural empyema, simultaneously to a respiratory virus outbreak. Physicians should be aware of this increased risk of pediatric iGAS infections, especially in settings with intense respiratory viruses' circulation.", "reading_min": 2, "pdf_file": null, "pubmed_url": "https://pubmed.ncbi.nlm.nih.gov/37180594/", "doi_url": "https://doi.org/10.1093/ofid/ofad188", "pmc_url": "https://europepmc.org/article/PMC/PMC10167988", "article_url": "https://doi.org/10.1093/ofid/ofad188"}]};
